/**
 * n8n Code node — "Select Spreadsheets"
 * Mode: Run Once for All Items
 *
 * Hardened 2026-08-04. Emits ONE item per SPREADSHEET attachment and nothing
 * else. Selection is by file extension (.xlsx/.xlsm/.xltx/.xls/.csv/.tsv,
 * case-insensitive, with trailing spaces/dots tolerated so
 * "3.08.2026 P&G .xlsx" and non-ASCII names like
 * "Ağustos-Nestle_FiyatListesi.xlsx" are kept) OR by spreadsheet MIME type
 * (for a mangled or missing filename). Inline images (image001.jpg signature
 * logos) and every other non-spreadsheet part are dropped. There is NO cap —
 * every matching attachment on the message is processed.
 */

const SPREADSHEET_EXT = /\.(xlsx|xlsm|xltx|xls|csv|tsv)\s*$/i;
const IMAGE_EXT = /\.(jpe?g|png|gif|bmp|svg|webp|tiff?|heic|ico)\s*$/i;
const SPREADSHEET_MIME = /(spreadsheetml|ms-excel|excel|csv|tab-separated|vnd\.oasis\.opendocument\.spreadsheet)/i;
const IMAGE_MIME = /^image\//i;

const out = [];
const skipped = [];

for (const item of $input.all()) {
  const binaries = item.binary || {};

  for (const [binaryKey, binary] of Object.entries(binaries)) {
    const rawName = binary && typeof binary.fileName === 'string' ? binary.fileName : '';
    const name = String(rawName || binaryKey).trim();
    const mime = String((binary && binary.mimeType) || '').trim();

    // Inline images and signature logos: never treat these as spreadsheets.
    const isImage = IMAGE_EXT.test(name) || IMAGE_MIME.test(mime);
    const isSpreadsheet = !isImage && (SPREADSHEET_EXT.test(name) || SPREADSHEET_MIME.test(mime));

    if (isSpreadsheet) {
      out.push({
        json: {
          binaryKey,
          fileName: name,
          mimeType: mime,
          messageId: item.json.id || item.json.messageId || null,
          threadId: item.json.threadId || null,
          subject: item.json.subject || '',
          from: item.json.from || '',
        },
        binary: { [binaryKey]: binary },
      });
    } else {
      skipped.push(name || binaryKey);
    }
  }
}

if (skipped.length) {
  console.log(`Select Spreadsheets: kept ${out.length}, skipped ${skipped.length} non-spreadsheet part(s): ${skipped.join(', ')}`);
}

return out;

/**
 * n8n Code node — "Read Workbook"
 * Mode: Run Once for All Items
 */

const GMAIL_NODE = 'Gmail Trigger';

let meta = {};
try {
  const g = $(GMAIL_NODE).first().json;
  const body = String(g.text || g.textAsHtml || g.html || g.snippet || '');
  const envelope = extractEmail(g.from ?? g.From ?? '');
  const forwarded = forwardedSender(body);
  const effective = (forwarded && forwarded.address) || envelope.address || '';
  const domain = (effective.split('@')[1] || '').toLowerCase();
  meta = {
    sourceMessageId: g.id || g.messageId || null,
    threadId: g.threadId || null,
    fromAddress: effective,
    envelopeFrom: envelope.address || '',
    forwardedFrom: forwarded ? forwarded.address : '',
    senderName: (forwarded && forwarded.name) || envelope.name || '',
    senderDomain: domain,
    senderFromForward: Boolean(forwarded),
    externalSender: Boolean(effective) && /@/.test(effective) && !/@akay\.ie$/i.test(effective),
    subject: g.subject || g.Subject || '',
  };
} catch (e) {
  meta = { sourceMessageId: null, threadId: null, fromAddress: '', envelopeFrom: '', forwardedFrom: '', senderName: '', senderDomain: '', senderFromForward: false, externalSender: false, subject: '' };
}

const items = $input.all();
if (items.length === 0) return [];

const rows = items.map((item) => toCellArray(item.json)).filter((r) => r.length > 0);
if (rows.length < 2) return [];

while (rows.length && rows[rows.length - 1].every((c) => String(c ?? '').trim() === '')) rows.pop();

return [{
  json: {
    ...meta,
    fileName: fileNameFor(items[0]),
    sheetName: sheetNameFor(),
    rows,
    rowCount: rows.length,
  },
}];

function toCellArray(json) {
  if (!json || typeof json !== 'object') return [];

  if (Array.isArray(json.row)) return json.row.map(cell);

  const indexed = Object.keys(json)
    .map((k) => ({ k, i: parseIndex(k) }))
    .filter((x) => x.i !== null)
    .sort((a, b) => a.i - b.i);

  if (indexed.length) {
    const out = [];
    for (const { k, i } of indexed) out[i] = cell(json[k]);
    return Array.from(out, (v) => v ?? '');
  }

  return Object.values(json).map(cell);
}

function parseIndex(key) {
  const m = String(key).match(/^(?:row_|col_|column_)?(\d+)$/i);
  return m ? Number(m[1]) : null;
}

function cell(v) {
  if (v === null || v === undefined) return '';
  if (v instanceof Date) return v;
  return String(v);
}

function fileNameFor(item) {
  const j = item.json || {};
  if (j.fileName) return j.fileName;
  const bin = item.binary && Object.values(item.binary)[0];
  if (bin && bin.fileName) return bin.fileName;
  try {
    const g = $(GMAIL_NODE).first();
    const gb = g.binary && Object.values(g.binary)[0];
    if (gb && gb.fileName) return gb.fileName;
  } catch (e) { /* trigger unavailable — fall through */ }
  return 'unknown.xlsx';
}

function sheetNameFor() {
  try {
    const n = $('Extract From File');
    const name = n.params && (n.params.options?.sheetName || n.params.sheetName);
    if (name) return String(name);
  } catch (e) { /* not resolvable at runtime */ }
  return 'Sheet1';
}

/**
 * Envelope sender as { address, name }. Gmail Trigger (simple:false) delivers
 * `from` as an OBJECT ({ value:[{address,name}], text, html }); the old code
 * String()-ified that to "[object object]", so supplier resolution by sender
 * never matched. Both the object and the raw "Name <addr>" string are handled.
 */
function extractEmail(raw) {
  if (raw && typeof raw === 'object') {
    const v = Array.isArray(raw.value) ? raw.value[0] : null;
    if (v && v.address) return { address: String(v.address).trim().toLowerCase(), name: String(v.name || '').trim() };
    return parseAddr(String(raw.text || raw.html || ''));
  }
  return parseAddr(String(raw));
}

function parseAddr(s) {
  const m = String(s).match(/<([^>]+)>/);
  const address = (m ? m[1] : String(s)).trim().toLowerCase();
  let name = '';
  const nm = String(s).match(/^\s*"?([^"<]+?)"?\s*</);
  if (nm) name = nm[1].trim();
  return { address, name };
}

/**
 * Real supplier from a FORWARDED body header. Offers arrive forwarded into
 * ak@akay.ie / offers@akay.ie, so the envelope sender is the forwarder, not the
 * supplier — the supplier sits in the "From:" line under the forward marker.
 * Returns { address, name } or null; null when the address is our own akay.ie
 * (a forward of our own mail is not a supplier), so we never auto-create from it.
 */
function forwardedSender(text) {
  const src = String(text);
  const fwd = src.match(/-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}/i)
           || src.match(/Begin forwarded message:/i);
  if (!fwd || fwd.index === undefined) return null;
  const header = src.slice(fwd.index, fwd.index + 800);
  const m = header.match(/\n\s*\*?\s*From:\s*\*?\s*(.*?)([^\s<>"]+@[^\s<>"]+\.[a-z]{2,})/i);
  if (!m) return null;
  const address = m[2].toLowerCase().replace(/[.,;>]+$/, '');
  if (/@akay\.ie$/i.test(address)) return null;
  const name = String(m[1] || '').replace(/[<"]/g, '').replace(/[-–\s]+$/, '').trim();
  return { address, name };
}

/**
 * n8n Code node — "Detect Header"
 * Mode: Run Once for All Items
 *
 * Splits each worksheet into SECTIONS and emits one item per section.
 */

const HEADER_MIN_SCORE = 3;
const MAX_CONTINUATION_ROWS = 2;

const HEADER_HINTS = [
  'product', 'description', 'brand', 'article', 'item', 'name',
  'price', 'eur', 'usd', 'cost', 'ppc', 'euro',
  'case', 'carton', 'ctn', 'pcs', 'units', 'pack', 'qty', 'quantity', 'stock', 'available',
  'volume', 'size', 'cl', 'ml', 'ltr', 'litre', 'content',
  'abv', 'alc', 'vol',
  'origin', 'country', 'ean', 'barcode', 'sku', 'code',
  'bond', 'customs', 'status', 't1', 't2', 'duty', 'incoterm', 'warehouse', 'delivery',
  'bbd', 'expiry', 'best before', 'moq', 'pallet', 'lead', 'variant', 'comment',
];

const out = [];

for (const input of $input.all()) {
  const item = input.json;
  const rows = item.rows || [];

  const sections = [];
  let i = 0;
  while (i < rows.length) {
    if (scoreAsHeader(rows[i], rows[i + 1]) < HEADER_MIN_SCORE) { i++; continue; }

    let headerCells = (rows[i] || []).map((c) => String(c ?? '').trim());
    let consumed = i;
    for (let n = 1; n <= MAX_CONTINUATION_ROWS; n++) {
      if (!isContinuationRow(rows[i + n], headerCells)) break;
      headerCells = mergeHeaderRow(headerCells, rows[i + n]);
      consumed = i + n;
    }

    sections.push({ start: i, consumed, headerCells });
    i = consumed + 1;
  }

  if (sections.length === 0) {
    out.push({ json: { ...item, rows: undefined, headerFound: false,
      exceptionReason: `No header row detected in "${item.sheetName}"` } });
    continue;
  }

  sections.forEach(({ start, consumed, headerCells }, s) => {
    const end = s + 1 < sections.length ? sections[s + 1].start : rows.length;
    const dataRows = rows.slice(consumed + 1, end)
      .filter((r) => r.some((c) => String(c ?? '').trim() !== ''));

    if (dataRows.length === 0) return;

    if (!hasPriceColumn(headerCells)) {
      out.push({ json: { ...item, rows: undefined, headerFound: false,
        sectionLabel: sectionLabel(headerCells),
        headerSample: headerCells.filter(Boolean).join(' | '),
        exceptionReason: `Section at row ${start} of "${item.sheetName}" has no price column — treated as a non-offer block` } });
      return;
    }

    out.push({
      json: {
        ...item,
        rows: undefined,
        headerFound: true,
        sectionIndex: s,
        sectionCount: sections.length,
        sectionLabel: sectionLabel(headerCells),
        headerRowIndex: start,
        dataStartRow: consumed + 1,
        headerCells,
        dataRows,
        rowCount: dataRows.length,
        fingerprint: fingerprint(headerCells),
        headerSample: headerCells.filter(Boolean).join(' | '),
        sampleRows: dataRows.slice(0, 5),
      },
    });
  });
}

return out;

function scoreAsHeader(row, next) {
  if (!Array.isArray(row)) return 0;

  const cells = row.map((c) => String(c ?? '').trim()).filter(Boolean);
  if (cells.length < 3) return 0;

  const numeric = cells.filter(isNumericish).length;
  if (numeric >= 2) return 0;

  let score = Math.min(cells.length, 8) * 0.5;

  for (const cell of cells) {
    const lower = cell.toLowerCase();
    if (HEADER_HINTS.some((h) => lower.includes(h))) score += 1.5;
  }

  score -= numeric * 1.5;

  if (Array.isArray(next)) {
    const nextCells = next.map((c) => String(c ?? '').trim()).filter(Boolean);
    if (nextCells.length >= 3 && nextCells.some(isNumericish)) score += 2;
  }

  return score;
}

function isContinuationRow(row, header) {
  if (!Array.isArray(row)) return false;

  const cells = row.map((c) => String(c ?? '').trim());
  const filled = cells.filter(Boolean);
  if (filled.length < 2) return false;
  if (filled.length > header.filter(Boolean).length) return false;
  if (filled.some(isNumericish)) return false;

  return filled.filter((c) => c.length <= 15).length >= Math.ceil(filled.length / 2);
}

function mergeHeaderRow(header, contRow) {
  const cont = (contRow || []).map((c) => String(c ?? '').trim());
  const width = Math.max(header.length, cont.length);
  const merged = [];

  for (let i = 0; i < width; i++) {
    const base = header[i] || '';
    const sub = cont[i] || '';
    merged.push(sub && sub.length <= 15 ? `${base} ${sub}`.trim() : base);
  }
  return merged;
}

function sectionLabel(headerCells) {
  const generic = /^(qty|quantity|cartons?|available|description|product|item)\b/i;
  const candidate = headerCells.find((c) => c && c.length <= 30 && !generic.test(c) && !/^\d/.test(c));
  return candidate || headerCells.find(Boolean) || '';
}

function hasPriceColumn(headerCells) {
  const PRICE_TOKENS = ['price', 'euro', 'eur', 'usd', 'gbp', 'cost', 'prijs', 'prezzo', '€', '$', '£'];
  return headerCells.some((c) => {
    const lower = String(c || '').toLowerCase();
    return PRICE_TOKENS.some((t) => lower.includes(t));
  });
}

function isNumericish(v) {
  const s = String(v).replace(/[\s€$£,]/g, '');
  return s !== '' && !Number.isNaN(Number(s.replace(',', '.')));
}

function fingerprint(cells) {
  const norm = cells
    .filter((c) => c && !isNumericish(c))
    .map((c) => c.toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(Boolean)
    .sort();
  return 'h' + djb2(norm.join('~')).toString(16).padStart(8, '0');
}

function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  }
  return h;
}

/**
 * n8n Code node — "Match Profile"
 * Mode: Run Once for All Items
 */

const sections = $('Detect Header').all();
const profileItems = $input.all();

const byFingerprint = new Map();
for (const p of profileItems) {
  const rec = p.json || {};
  const fp = rec['Header Fingerprint'];
  if (fp && !byFingerprint.has(fp)) byFingerprint.set(fp, rec);
}

const out = [];
for (const s of sections) {
  const item = s.json || {};

  if (!item.headerFound || !item.fingerprint) {
    out.push({ json: { ...item, profileFound: false } });
    continue;
  }

  const rec = byFingerprint.get(item.fingerprint);
  if (!rec) {
    out.push({ json: { ...item, profileFound: false } });
    continue;
  }

  let columnMap = {};
  let profileDefaults = {};
  try { columnMap = JSON.parse(rec['Column Map'] || '{}'); } catch (e) {}
  try { profileDefaults = JSON.parse(rec['Defaults'] || '{}'); } catch (e) {}

  const supplierLink = rec['Supplier'];
  const supplierRecordId = Array.isArray(supplierLink) && supplierLink.length ? supplierLink[0] : null;

  out.push({
    json: {
      ...item,
      profileFound: true,
      profileId: rec.id || null,
      columnMap,
      profileDefaults,
      supplierRecordId,
      supplierValidityDays: rec['Validity Days'] ?? null,
    },
  });
}

return out;

/**
 * n8n Code node — "Normalize Rows"
 * Mode: Run Once for Each Item
 */

const OPTIONS = {
  currency: ['EUR', 'USD', 'GBP', 'AED', 'SGD', 'Other'],
  unitType: ['Bottle', 'Can', 'Jar', 'Pack', 'Piece', 'Other'],
  priceType: ['Per Case', 'Per Bottle', 'Per Can', 'Per Piece', 'Per Pack', 'Per Jar'],
  bond: ['Bonded', 'T1', 'T2', 'Duty Paid', 'On Floor', 'Other'],
  incoterm: ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP', 'Other'],
  warehouse: ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
              'Greece', 'Indonesia', 'Czech', 'Other', 'NewCorp', 'Vergèze', 'Bergamo'],
  category: ['Beer', 'Spirits', 'Champagne', 'Grocery', 'Confectionery',
             'Toiletries', 'Soft Drinks', 'Other FMCG'],
};

const VOLUME_UNIT_FACTOR = { ml: 1, cc: 1, cl: 10, dl: 100, l: 1000, ltr: 1000, litre: 1000 };

const pad = (v) => String(v).padStart(2, '0');

const SYNONYMS = {
  currency: {
    '€': 'EUR', eur: 'EUR', euro: 'EUR', euros: 'EUR',
    $: 'USD', usd: 'USD', dollar: 'USD', usdollar: 'USD',
    '£': 'GBP', gbp: 'GBP', pound: 'GBP', sterling: 'GBP',
    aed: 'AED', dirham: 'AED', sgd: 'SGD',
  },
  bond: {
    bond: 'Bonded', bonded: 'Bonded', underbond: 'Bonded', inbond: 'Bonded',
    t1: 'T1', t2: 'T2', export: 'T1', eu: 'T2', community: 'T2',
    dutypaid: 'Duty Paid', dp: 'Duty Paid', taxpaid: 'Duty Paid',
    onfloor: 'On Floor', floor: 'On Floor', exstock: 'On Floor',
  },
  unitType: {
    bottle: 'Bottle', btl: 'Bottle', flasche: 'Bottle', bouteille: 'Bottle',
    can: 'Can', cans: 'Can', tin: 'Can',
    jar: 'Jar', pack: 'Pack', pouch: 'Pack', piece: 'Piece', pcs: 'Piece', unit: 'Piece',
  },
  category: {
    beer: 'Beer', lager: 'Beer', ale: 'Beer', cider: 'Beer',
    spirit: 'Spirits', spirits: 'Spirits', whisky: 'Spirits', whiskey: 'Spirits',
    vodka: 'Spirits', gin: 'Spirits', rum: 'Spirits', liqueur: 'Spirits',
    cognac: 'Spirits', brandy: 'Spirits', tequila: 'Spirits',
    champagne: 'Champagne', wine: 'Champagne', wines: 'Champagne',
    prosecco: 'Champagne', sparkling: 'Champagne', cava: 'Champagne', bordeaux: 'Champagne',
    softdrink: 'Soft Drinks', softdrinks: 'Soft Drinks', water: 'Soft Drinks',
    juice: 'Soft Drinks', energy: 'Soft Drinks', soda: 'Soft Drinks',
    grocery: 'Grocery', food: 'Grocery',
    confectionery: 'Confectionery', chocolate: 'Confectionery', sweets: 'Confectionery',
    candy: 'Confectionery', biscuit: 'Confectionery',
    toiletries: 'Toiletries', cosmetics: 'Toiletries', personalcare: 'Toiletries',
  },
};

const item = $input.item.json;
const map = item.columnMap || {};
const defaults = item.profileDefaults || {};
const headers = item.headerCells || [];

// No usable column map (the LLM mapping failed / needs review, or a stored
// profile is malformed). Emit ONE visible exception instead of silently
// dropping every row as 0 — so Build Airtable Payload surfaces it and the
// section is routed to review rather than vanishing.
if (map.productName === undefined || map.buyPrice === undefined) {
  return {
    json: {
      fileName: item.fileName,
      sheetName: item.sheetName,
      sourceMessageId: item.sourceMessageId,
      fromAddress: item.fromAddress,
      supplierRecordId: item.supplierRecordId || null,
      profileId: item.profileId || null,
      fingerprint: item.fingerprint,
      parsedCount: 0,
      exceptionCount: 1,
      offers: [],
      exceptions: [{
        sheetRow: item.headerRowIndex ?? null,
        productName: '',
        exceptionReason: item.exceptionReason
          || 'No usable column map (needs review): LLM mapping did not yield productName + buyPrice for this section',
        sourceSheet: `${item.fileName} :: ${item.sheetName}`,
      }],
      needsReview: true,
    },
  };
}

const offers = [];
const exceptions = [];

(item.dataRows || []).forEach((row, i) => {
  const sheetRow = (item.headerRowIndex ?? 0) + 2 + i;
  const get = (field) => {
    const idx = map[field];
    if (idx === undefined || idx === null) return '';
    return String(row[idx] ?? '').trim();
  };

  const productName = get('productName');
  const rawPrice = get('buyPrice');

  if (!productName && !rawPrice) return;

  const problems = [];

  const price = parsePriceCell(rawPrice);
  if (!productName) problems.push('missing product name');
  if (price.value === null) problems.push(`unparseable price "${rawPrice}"`);
  else if (price.ambiguous) problems.push(`ambiguous decimal separator in "${rawPrice}"`);

  const pack = parsePack(get('packFormat') || get('volumeMl') || productName);

  const volume = parseVolume(get('volumeMl'), defaults.volumeUnit)
    ?? pack.volumeMl
    ?? parseVolume(productName, defaults.volumeUnit);
  const pcsCase = parseNumber(get('pcsCase')).value ?? pack.pcsCase;
  const abv = parseAbv(get('abv')) ?? pack.abv ?? parseAbv(productName);
  const weightKg = pack.weightG !== null ? pack.weightG / 1000 : null;

  const bond = coerce('bond', get('bondStatus') || defaults.bondStatus);
  // Currency actually STATED on the row/sheet (symbol on the price, or a
  // dedicated currency column) vs. merely inherited from the profile default.
  // When nothing is stated, the resolved supplier's Default Currency should win
  // downstream (Build Airtable Payload), so track which case this is.
  const statedCurrency = price.currency || coerce('currency', get('currency'));
  const currency = statedCurrency || coerce('currency', defaults.currency);
  const currencyStated = Boolean(statedCurrency);
  if (!currency) problems.push('no currency on row or profile default');

  const brand = get('brand') || guessBrand(productName);

  const record = {
    sheetRow,
    sourceSheet: `${item.fileName} :: ${item.sheetName}`,
    sourceMessageId: item.sourceMessageId,

    brand,
    productName,
    variant: get('variant') || '',
    category: coerce('category', get('category') || defaults.category),
    volumeMl: volume,
    pcsCase: pcsCase ?? defaults.pcsCase ?? null,
    unitType: coerce('unitType', get('unitType') || defaults.unitType) || 'Bottle',
    abv,
    originCountry: get('originCountry') || defaults.originCountry || '',
    bondStatus: bond,
    buyPrice: price.value,
    currency,
    priceType: price.basis
      || coerce('priceType', get('priceType') || defaults.priceType)
      || 'Per Case',
    priceBasisStated: Boolean(price.basis),
    currencyStated,
    weightKg,
    stockCases: toCases(parseNumber(get('stockCases')).value, pcsCase, defaults.stockUnit),
    casesPerPallet: parseNumber(get('casesPerPallet')).value,
    piecesPerPallet: parseNumber(get('piecesPerPallet')).value,
    language: get('language') || '',
    moq: get('moq') || '',
    leadTime: get('leadTime') || '',
    eanUnit: cleanEan(get('eanUnit')),
    eanCase: cleanEan(get('eanCase')),
    bbd: parseDate(get('bbd')),
    incoterm: coerce('incoterm', get('incoterm') || defaults.incoterm),
    warehouse: coerce('warehouse', get('warehouse') || defaults.warehouse),

    productKey: buildProductKey(brand, productName, volume, bond),
  };

  if (problems.length) {
    exceptions.push({ ...record, exceptionReason: problems.join('; ') });
  } else {
    offers.push(record);
  }
});

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    sourceMessageId: item.sourceMessageId,
    fromAddress: item.fromAddress,
    supplierRecordId: item.supplierRecordId || null,
    profileId: item.profileId || null,
    fingerprint: item.fingerprint,
    parsedCount: offers.length,
    exceptionCount: exceptions.length,
    offers,
    exceptions,
  },
};

function parseNumber(raw) {
  if (raw === null || raw === undefined) return { value: null, ambiguous: false };
  let s = String(raw).trim();
  if (!s) return { value: null, ambiguous: false };

  s = s.replace(/euros?|dollars?|pounds?|usd|gbp|aed|sgd|eur|[€$£\s]/gi, '').trim();
  if (!s) return { value: null, ambiguous: false };

  if (/[a-z]/i.test(s)) return { value: null, ambiguous: false };

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');
  let ambiguous = false;

  if (hasDot && hasComma) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (hasComma) {
    const after = s.split(',')[1] ?? '';
    if (s.split(',').length > 2) s = s.replace(/,/g, '');
    else if (after.length === 3) ambiguous = true;
    else s = s.replace(',', '.');
    if (ambiguous) s = s.replace(',', '.');
  }

  const cleaned = s.replace(/[^0-9.\-]/g, '');
  if (!/\d/.test(cleaned)) return { value: null, ambiguous: false };

  const n = Number(cleaned);
  return Number.isFinite(n) ? { value: n, ambiguous } : { value: null, ambiguous: false };
}

function parsePriceCell(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return { value: null, currency: null, basis: null, ambiguous: false };

  let currency = null;
  if (/€|\beur(o|os)?\b/i.test(s)) currency = 'EUR';
  else if (/£|\bgbp\b|\bpounds?\b/i.test(s)) currency = 'GBP';
  else if (/\$|\busd\b|\bdollars?\b/i.test(s)) currency = 'USD';
  else if (/\baed\b/i.test(s)) currency = 'AED';
  else if (/\bsgd\b/i.test(s)) currency = 'SGD';

  let basis = null;
  const m = s.match(/\/\s*(btl|bottle|cs|case|ctn|carton|pc|pcs|piece|pack|can|jar|unit)\b/i);
  if (m) {
    const k = m[1].toLowerCase();
    if (/^(cs|case|ctn|carton)$/.test(k)) basis = 'Per Case';
    else if (/^(btl|bottle)$/.test(k)) basis = 'Per Bottle';
    else if (/^(pc|pcs|piece|unit)$/.test(k)) basis = 'Per Piece';
    else if (k === 'pack') basis = 'Per Pack';
    else if (k === 'can') basis = 'Per Can';
    else if (k === 'jar') basis = 'Per Jar';
  }

  const numeric = parseNumber(s.replace(/\/\s*[a-z]+\b/gi, ''));

  return { value: numeric.value, currency, basis, ambiguous: numeric.ambiguous };
}

function parsePack(raw) {
  const s = String(raw ?? '').trim();
  const out = { pcsCase: null, volumeMl: null, abv: null, weightG: null };
  if (!s) return out;

  let m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(g|gr|gram|kg)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    const n = Number(m[2].replace(',', '.'));
    out.weightG = /^kg$/i.test(m[3]) ? n * 1000 : n;
    return out;
  }

  m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    out.volumeMl = parseVolume(`${m[2]}${m[3]}`);
    const abv = s.match(/(\d+(?:[.,]\d+)?)\s*%/);
    if (abv) out.abv = Number(abv[1].replace(',', '.'));
    return out;
  }

  m = s.match(/(\d+)\s*\/\s*(\d+(?:[.,]\d+)?)\s*(?:\/\s*(\d+(?:[.,]\d+)?))?/);
  if (m) {
    out.pcsCase = Number(m[1]);
    const mid = Number(m[2].replace(',', '.'));
    out.volumeMl = mid >= 200 ? Math.round(mid) : Math.round(mid * 10);
    if (m[3]) {
      const a = Number(m[3].replace(',', '.'));
      if (a > 0 && a <= 100) out.abv = a;
    }
  }
  return out;
}

function parseVolume(raw, unitHint) {
  const s = String(raw ?? '').toLowerCase();
  if (!s) return null;

  let m = s.match(/(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr|litre|liter|cc)\b/);
  if (!m) {
    const bare = parseNumber(s).value;
    if (bare === null) return null;

    const factor = VOLUME_UNIT_FACTOR[String(unitHint || '').toLowerCase()];
    if (factor) return Math.round(bare * factor);

    return bare > 0 && bare < 10 ? Math.round(bare * 1000) : Math.round(bare);
  }

  const n = Number(m[1].replace(',', '.'));
  switch (m[2]) {
    case 'ml': case 'cc': return Math.round(n);
    case 'cl': return Math.round(n * 10);
    case 'dl': return Math.round(n * 100);
    default: return Math.round(n * 1000);
  }
}

function toCases(value, pcsCase, stockUnit) {
  if (value === null || value === undefined) return null;
  if (String(stockUnit || '').toLowerCase() !== 'pcs') return value;
  if (!pcsCase || pcsCase <= 0) return null;
  return Math.floor(value / pcsCase);
}

function parseAbv(raw) {
  const s = String(raw ?? '');
  const m = s.match(/(\d+(?:[.,]\d+)?)\s*%/) || s.match(/^(\d+(?:[.,]\d+)?)$/);
  if (!m) return null;
  const n = Number(m[1].replace(',', '.'));
  return n > 0 && n <= 100 ? n : null;
}

function parseDate(raw) {
  if (!raw) return null;
  if (raw instanceof Date && !isNaN(raw)) return raw.toISOString().slice(0, 10);

  const s = String(raw).trim();
  if (!s) return null;

  if (/^\d{5}$/.test(s)) {
    const ms = (Number(s) - 25569) * 86400 * 1000;
    return new Date(ms).toISOString().slice(0, 10);
  }

  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;

  m = s.match(/^([a-z]{3,9})\.?\s+(\d{4})$/i);
  if (m) {
    const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    const idx = months.indexOf(m[1].slice(0, 3).toLowerCase());
    if (idx >= 0) return `${m[2]}-${pad(idx + 1)}-01`;
  }

  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
  if (m) {
    let [, a, b, y] = m;
    if (y.length === 2) y = '20' + y;
    const dayFirst = Number(a) > 12 || Number(b) <= 12;
    const day = dayFirst ? a : b;
    const month = dayFirst ? b : a;
    return `${y}-${pad(month)}-${pad(day)}`;
  }

  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
}

function coerce(kind, raw) {
  const s = String(raw ?? '').trim();
  if (!s) return null;

  const exact = OPTIONS[kind].find((o) => o.toLowerCase() === s.toLowerCase());
  if (exact) return exact;

  const key = s.toLowerCase().replace(/[^a-z0-9€$£]/g, '');
  const syn = (SYNONYMS[kind] || {})[key];
  if (syn) return syn;

  for (const [k, v] of Object.entries(SYNONYMS[kind] || {})) {
    if (key.includes(k)) return v;
  }

  return OPTIONS[kind].includes('Other') ? 'Other' : null;
}

function cleanEan(raw) {
  const digits = String(raw ?? '').replace(/\D/g, '');
  return /^\d{8}$|^\d{12,14}$/.test(digits) ? digits : '';
}

function guessBrand(name) {
  const first = String(name).trim().split(/\s+/)[0] || '';
  return first.length > 1 ? first : '';
}

function buildProductKey(brand, name, volumeMl, bond) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(brand), n(name), volumeMl ?? '', n(bond)].join('|');
}

/**
 * n8n Code node — "Build Airtable Payload"
 * Mode: Run Once for All Items
 *
 * Turns normalised spreadsheet rows into Airtable Offers records.
 *
 * ── PRODUCT MATCH KEY FIXED 2026-08-03 ──────────────────────────────────────
 * This node used to key the product index on
 *     Brand | Product Name | Volume | Bond status
 * and that is why roughly 89% of offers ended up with no Products link and were
 * therefore invisible to price comparison (Is Cheapest, Cheaper By 5%+).
 *
 * The reason is data, not logic: BRAND IS EMPTY ON THE LARGE MAJORITY OF PRODUCT
 * RECORDS, and Bond/Customs Status is blank on most of them too. Meanwhile the
 * offer side has no brand column on most sheets either, so Normalize Rows falls
 * back to guessBrand() - the FIRST WORD of the product name. So the offer key
 * carried a brand like "ardbeg" while the product key carried an empty string,
 * the two never matched, and every lookup missed. The linking was always being
 * attempted; the key was simply unmatchable.
 *
 * Matching is now on NORMALISED PRODUCT NAME + VOLUME, which are the two fields
 * the Products table actually populates (Product Key there is just the lowercased
 * product name). Brand and Bond are deliberately excluded rather than
 * "improved": including a field that is blank on one side of the comparison can
 * only ever destroy matches.
 *
 * Volume stays IN the key. Dropping it would merge a 70cl and a 1L of the same
 * label into one product and attach offers to the wrong pack size, which is a
 * worse failure than not matching at all.
 *
 * Offer.productKey from Normalize Rows is still carried through for the Notes
 * message and the in-run duplicate guard, but is no longer used for lookup.
 *
 * ── EARLIER CHANGES (2026-07-31, Anil) ─────────────────────────────────────
 *  1. DEFAULT VALIDITY IS NOW 30 DAYS (was 14).
 *  2. RE-INGESTION GUARD. Nothing previously stopped the same email being
 *     parsed twice.
 *  3. SUPPLIER RESOLUTION BY SENDER EMAIL. Previously the supplier came ONLY
 *     from the Sheet Profile's link, so any offer parsed on the LLM
 *     profile-miss path was written with no Supplier at all.
 *  4. EMAIL PROVENANCE ON THE RECORD. Sender, subject and thread are now
 *     written into Notes.
 *
 * Also: offers whose Product does not match are CREATED rather than discarded.
 * They previously went to a toReview array that nothing ever wrote, so with
 * Create Offers enabled they would have been silently dropped. The Products link
 * is left blank and the offer is flagged in Notes; the hourly "Link Offers To
 * Products" workflow then picks it up and can create the Product if needed.
 */

// Raised from 14 to 30 by Anil, 2026-07-31. Used only when the resolved
// supplier has no Default Validity Days of its own.
const FALLBACK_VALIDITY_DAYS = 30;

// Formula and lookup fields — writing to any of these errors the batch.
// Supplier Email/Country/Trust are LOOKUPS through the Supplier link, so
// linking the supplier is what populates them; they must never be written.
const READ_ONLY = new Set([
  'Sell Price', 'Pack Format', 'Is Expired', 'Auto Expiry Date', 'Send Eligible',
  'Public Listing', 'Public Product Description', 'Public Spec', 'Price Display',
  'Public Terms', 'Stock Display', 'whatsapp link',
  'Supplier Name', 'Supplier Email', 'Supplier Country',
  'Supplier Trust Level', 'Supplier Payment Terms',
]);

const products  = nodeRows('Fetch Products');
const suppliers = nodeRows('Fetch Suppliers');
const ingested  = nodeRows('Fetch Ingested Message IDs');
const sections  = $('Normalize Rows').all().map((s) => s.json || {});

const today = new Date().toISOString().slice(0, 10);

const productIndex   = buildProductIndex(products);
const supplierByMail = buildSupplierIndex(suppliers);
const alreadyIngested = new Set(
  ingested.map((r) => normaliseMessageId((r.fields || r)['Source Message ID'])).filter(Boolean)
);

const toCreate   = [];
const skipped    = [];
const exceptions = [];
const summaries  = [];

// Guards against the same row being emitted twice inside ONE run — possible
// when two detected sections overlap on the same block of the sheet.
const seenInRun = new Set();

for (const item of sections) {
  const msgId = normaliseMessageId(item.sourceMessageId);

  // ---- Re-ingestion guard -------------------------------------------------
  // The ID set was read once at the start of this run, so it reflects what was
  // in Airtable BEFORE this execution. A message ID already present therefore
  // means this email was ingested on an earlier run, and the whole section is
  // skipped. It does NOT mean "this row is a duplicate of another row in the
  // same workbook" — one email legitimately produces many offers sharing one
  // message ID, which is exactly why this check happens per SECTION and not
  // per offer.
  if (msgId && alreadyIngested.has(msgId)) {
    skipped.push({
      fileName: item.fileName,
      sheetName: item.sheetName,
      sourceMessageId: item.sourceMessageId,
      offersSkipped: (item.offers || []).length,
      reason: `Message ${msgId} is already present in Offers — email previously ingested, nothing created`,
    });
    summaries.push(`${item.fileName} :: ${item.sheetName} — SKIPPED, already ingested`);
    continue;
  }

  // ---- Supplier resolution ------------------------------------------------
  const resolved = resolveSupplier(item, supplierByMail);

  // Validity comes from the supplier record when we have one. The old code read
  // rec['Validity Days'] off the Sheet Profile, a field that does not exist
  // there — the real one is Suppliers.Default Validity Days — so every offer
  // silently fell back to the default.
  const validityDays = Number(resolved.validityDays) > 0
    ? Number(resolved.validityDays)
    : FALLBACK_VALIDITY_DAYS;

  let created = 0;
  let unlinked = 0;

  for (const offer of item.offers || []) {
    const rowKey = [msgId, offer.productKey, offer.buyPrice].join('~');
    if (seenInRun.has(rowKey)) continue;
    seenInRun.add(rowKey);

    // Name + volume, NOT the brand/bond key — see the header note.
    const matchKey = productMatchKey(offer.productName, offer.volumeMl);
    const productId = productIndex.get(matchKey) || null;

    // Currency fallback: when the sheet stated no currency, apply the resolved
    // supplier's Default Currency (e.g. Halitlar = USD). A stated currency
    // always wins; with no stated currency and no supplier default, the
    // profile default carried on the offer stands.
    const offerCurrency = (!offer.currencyStated && resolved.defaultCurrency)
      ? resolved.defaultCurrency
      : offer.currency;

    const fields = {
      'Offer Name': buildOfferName(offer, resolved.supplierName),
      'Status': 'Live',
      'Offer Date': today,
      'Auto Expiry Days': validityDays,

      'Brand': offer.brand || '',
      'Product Name': offer.productName,
      'Variant': offer.variant || '',
      'Volume ML': offer.volumeMl,
      'PCS/Case': offer.pcsCase,
      'Unit Type': offer.unitType,
      'ABV': offer.abv,
      'Origin Country': offer.originCountry || '',
      'Bond/Customs Status': offer.bondStatus,
      'Buy Price': offer.buyPrice,
      'Currency': offerCurrency,
      'Price Type': offer.priceType,
      'Stock Cases': offer.stockCases,
      'Weight KG': offer.weightKg,
      'Cases per Pallet': offer.casesPerPallet,
      'Pieces per Pallet': offer.piecesPerPallet,
      'Language': offer.language || '',
      'MOQ': offer.moq || '',
      'Lead Time': offer.leadTime || '',
      'EAN Unit': offer.eanUnit || '',
      'EAN Case': offer.eanCase || '',
      'BBD': offer.bbd,
      'Incoterm': offer.incoterm,
      'Warehouse': offer.warehouse,

      'Source Sheet': offer.sourceSheet,
      'Source Message ID': item.sourceMessageId || '',
      'Notes': buildNotes(item, offer, resolved, productId, matchKey, today),
    };

    if (offer.category) fields['Category'] = offer.category;

    // Linking the Supplier is also what populates the read-only Supplier Email,
    // Supplier Country and Supplier Trust Level lookups on the offer.
    if (resolved.supplierRecordId) fields['Supplier'] = [resolved.supplierRecordId];

    if (productId) fields['Products'] = [productId];
    else unlinked++;

    toCreate.push({ fields: stripEmpty(fields) });
    created++;
  }

  for (const e of item.exceptions || []) {
    exceptions.push({
      sheetRow: e.sheetRow,
      productName: e.productName,
      reason: e.exceptionReason,
      sourceSheet: e.sourceSheet,
    });
  }

  summaries.push(
    `${item.fileName} :: ${item.sheetName} — ${created} offers ` +
    `(${unlinked} without a Product link), ` +
    `${(item.exceptions || []).length} bad rows, ` +
    `supplier: ${resolved.supplierName || 'UNRESOLVED'} via ${resolved.via}, ` +
    `expiry ${validityDays}d`
  );
}

return [{
  json: {
    createCount: toCreate.length,
    skippedCount: skipped.length,
    exceptionCount: exceptions.length,
    toCreate,
    skipped,
    exceptions,
    summary: summaries.join(' | ') || 'nothing to do',
  },
}];

// ── helpers ──────────────────────────────────────────────────────────

/** Rows from a named Airtable node, or [] when it did not run. */
function nodeRows(name) {
  try { return $(name).all().map((i) => i.json || {}); }
  catch (e) { return []; }
}

/**
 * Strip the mailbox prefix from a Gmail message ID before comparing.
 *
 * The base holds BOTH "19fadb488e2d3ea9" and
 * "gmail:offers@akay.ie:19fadb488e2d3ea9" for the same message. They do not
 * string-match, so an exact comparison silently misses one of the two formats —
 * this is the confirmed cause of the CSE Ltd. Jameson, Newport Global, EZATA
 * Drinks and Yael Dahan duplicate batches. Take the last colon-separated
 * segment and lowercase it.
 */
function normaliseMessageId(v) {
  const s = String(v ?? '').trim();
  if (!s) return '';
  const parts = s.split(':');
  return parts[parts.length - 1].trim().toLowerCase();
}

/**
 * The single definition of how an Offer is matched to a Product.
 *
 * Punctuation and spacing are stripped entirely, so "Aberlour A'Bunadh Batch 77"
 * and "Aberlour ABunadh Batch 77" agree - supplier sheets are inconsistent about
 * apostrophes, hyphens and double spaces, and those differences are never
 * meaningful. Volume is kept as a plain number so 700 and "700" agree.
 */
function productMatchKey(name, volumeMl) {
  const n = String(name ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const v = (volumeMl === null || volumeMl === undefined || volumeMl === '') ? '' : Number(volumeMl);
  return n + '|' + v;
}

function buildProductIndex(rows) {
  const index = new Map();
  for (const p of rows) {
    const f = p.fields || p;
    if (!p.id) continue;
    const key = productMatchKey(f['Product Name'], f['Volume ML']);
    if (!index.has(key)) index.set(key, p.id);
  }
  return index;
}

/** Suppliers keyed by full email address AND by bare domain. */
function buildSupplierIndex(rows) {
  const byAddress = new Map();
  const byDomain = new Map();

  for (const s of rows) {
    const f = s.fields || s;
    if (!s.id) continue;
    const email = String(f['Email'] || '').trim().toLowerCase();
    if (!email) continue;

    const rec = {
      id: s.id,
      name: f['Supplier Name'] || null,
      validityDays: f['Default Validity Days'] ?? null,
      defaultCurrency: selectName(f['Default Currency']) || null,
      status: f['Status'] || null,
      skip: Boolean(f['Skip Offer Ingestion']),
    };

    if (!byAddress.has(email)) byAddress.set(email, rec);

    const domain = email.split('@')[1];
    // A domain is only a usable key while exactly one supplier uses it. Two
    // suppliers on one domain (or a shared host like gmail.com) makes the
    // domain ambiguous, so it is removed rather than guessed at.
    if (domain) {
      if (byDomain.has(domain)) byDomain.set(domain, null);
      else byDomain.set(domain, rec);
    }
  }
  return { byAddress, byDomain };
}

/**
 * Work out which supplier this workbook belongs to.
 *
 * Order matters. The Sheet Profile's own Supplier link is authoritative because
 * a human (or a reviewed LLM mapping) tied that header fingerprint to that
 * supplier. Only when there is no profile link do we fall back to the sending
 * address — which is the case that used to produce offers with no supplier at
 * all, on the profile-miss path.
 *
 * Generic mailbox domains are deliberately NOT domain-matched: several
 * suppliers use hotmail/gmail addresses, so a domain hit there means nothing.
 */
function resolveSupplier(item, index) {
  const GENERIC = new Set([
    'gmail.com', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'yahoo.com',
    'yahoo.co.uk', 'live.com', 'icloud.com', 'aol.com', 'protonmail.com', 'gmx.com',
  ]);

  if (item.supplierRecordId) {
    // Enrich from the fetched supplier list when we can, for validity days and
    // the name used in the internal Offer Name.
    const match = [...index.byAddress.values()].find((s) => s.id === item.supplierRecordId);
    return {
      supplierRecordId: item.supplierRecordId,
      supplierName: match ? match.name : null,
      validityDays: match ? match.validityDays : null,
      defaultCurrency: match ? match.defaultCurrency : null,
      via: 'sheet profile link',
    };
  }

  const from = String(item.fromAddress || '').trim().toLowerCase();
  if (from) {
    const exact = index.byAddress.get(from);
    if (exact) {
      return {
        supplierRecordId: exact.id,
        supplierName: exact.name,
        validityDays: exact.validityDays,
        defaultCurrency: exact.defaultCurrency,
        via: `sender address ${from}`,
      };
    }

    const domain = from.split('@')[1];
    if (domain && !GENERIC.has(domain)) {
      const byDom = index.byDomain.get(domain);
      if (byDom) {
        return {
          supplierRecordId: byDom.id,
          supplierName: byDom.name,
          validityDays: byDom.validityDays,
          defaultCurrency: byDom.defaultCurrency,
          via: `sender domain ${domain}`,
        };
      }
    }
  }

  // Resolve-or-auto-create fallback. A supplier matched from — or auto-created
  // for — the forwarded sender at run level by the Resolve Supplier / Create
  // Missing Supplier / Merge Supplier branch. Reached only when neither the
  // Sheet Profile link nor a direct sender match found one. When this is also
  // empty the sender was our own akay.ie (or otherwise not external): the offer
  // is left UNRESOLVED with a NEEDS ATTENTION note rather than inventing a
  // supplier from our own address.
  const run = runSupplier();
  if (run && run.supplierRecordId) {
    return {
      supplierRecordId: run.supplierRecordId,
      supplierName: run.supplierName || null,
      validityDays: run.validityDays ?? null,
      defaultCurrency: run.defaultCurrency || null,
      via: run.via || 'resolve-or-auto-create',
    };
  }

  return { supplierRecordId: null, supplierName: null, validityDays: null, defaultCurrency: null, via: 'UNRESOLVED' };
}

/**
 * Internal provenance for the offer. Notes is flagged INTERNAL ONLY on this
 * table and must never be mapped into Softr, which is why the sender address
 * and thread ID can live here. Public text belongs in Public Note.
 */
function buildNotes(item, offer, resolved, productId, matchKey, today) {
  const lines = [
    `Ingested from spreadsheet ${offer.sourceSheet} row ${offer.sheetRow} on ${today}.`,
    `Email: from ${item.fromAddress || '(sender unknown)'}` +
      `${item.subject ? `, subject "${item.subject}"` : ''}` +
      `${item.threadId ? `, thread ${item.threadId}` : ''}.`,
    `Supplier resolved via ${resolved.via}` +
      `${resolved.supplierName ? ` (${resolved.supplierName})` : ''}.`,
  ];

  if (!resolved.supplierRecordId) {
    lines.push('NEEDS ATTENTION: no Supplier could be matched from the Sheet Profile or the sending address. Set the Supplier link by hand — without it this offer has no supplier email, country or trust level.');
  }
  if (!productId) {
    lines.push(`No Product matched name+volume key "${matchKey}", so the Products link is blank and this offer is not yet visible to price comparison. The hourly Link Offers To Products workflow will match it, or create the Product if the offer has both a name and a volume.`);
  }
  return lines.join(' ');
}

/**
 * Offer Name is the primary field and is explicitly INTERNAL, so it may carry
 * the supplier name. Public display uses Public Product Description.
 */
function buildOfferName(offer, supplierName) {
  const parts = [offer.brand, offer.productName, offer.variant].filter(Boolean);
  const spec = offer.volumeMl ? `${offer.volumeMl}ml` : '';
  const supplier = supplierName ? ` - ${supplierName}` : '';
  return `${parts.join(' ')}${spec ? ' ' + spec : ''}${supplier} ${new Date().toISOString().slice(0, 10)}`.trim();
}

/** Airtable rejects null on some field types; omit rather than send empties. */
function stripEmpty(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields)) {
    if (READ_ONLY.has(k)) continue;
    if (v === null || v === undefined || v === '') continue;
    out[k] = v;
  }
  return out;
}

/**
 * Run-level supplier from the Resolve/Create/Merge branch (Merge Supplier).
 * Empty when that branch produced no supplier — e.g. an internal-only sender.
 */
function runSupplier() {
  try { return $('Merge Supplier').first().json || null; }
  catch (e) { return null; }
}

/** Airtable singleSelect value: {id,name} object over the REST client, or a
 * bare string. Return the plain name either way. */
function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Expand Offers"
 * Mode: Run Once for All Items
 *
 * Expands the matched toCreate[] into one flat record item each for
 * Create Offers (autoMapInputData), and stamps the trust-driven Offer
 * Approval Status on every record (Anil, 2026-08-04):
 *
 *   supplier Trust Score High, Medium or Low  -> Approved
 *   Trust = Hold, or no resolvable supplier   -> Awaiting Approval
 *
 * Offer Approval Status is a PROCESSING status feeding Send Eligible and the
 * Public Listing formula. It is NOT a human control point — the two human
 * approvals (Listing Approved on the website, Gate 2 dispatch approval, each
 * by Anil or Annika) are never written by ingestion, so an auto-approved
 * offer still cannot reach the public site or a client inbox on its own.
 *
 * Trust is read per record via the Supplier link id against the run's
 * Fetch Suppliers snapshot. A Supplier id NOT in that snapshot was created
 * THIS run by Create Missing Supplier, which always writes Trust = Medium
 * (Hard Rule 8) -> Approved.
 */

const AUTO_APPROVE = new Set(['high', 'medium', 'low']);

// Supplier id -> Trust Score name, from the run's supplier snapshot.
const trustById = new Map();
try {
  for (const s of $('Fetch Suppliers').all()) {
    const j = s.json || {};
    const f = j.fields || j;
    if (j.id) trustById.set(j.id, selectName(f['Trust Score']));
  }
} catch (e) { /* snapshot unavailable — falls through to Awaiting Approval */ }

const out = [];
for (const it of $input.all()) {
  const recs = (it.json && it.json.toCreate) || [];
  for (const r of recs) {
    const rec = r.fields || r;

    const supplierId = Array.isArray(rec['Supplier']) && rec['Supplier'].length
      ? rec['Supplier'][0] : null;

    let trust = supplierId ? trustById.get(supplierId) : null;
    // Not in the snapshot but linked => auto-created this run at Medium.
    if (supplierId && trust === undefined) trust = 'Medium';

    const approved = AUTO_APPROVE.has(String(trust || '').toLowerCase());
    rec['Offer Approval Status'] = approved ? 'Approved' : 'Awaiting Approval';
    if (!approved) {
      rec['Notes'] = `${rec['Notes'] || ''} HELD at Awaiting Approval: supplier trust is ${trust || 'unknown/unresolved'} — only Hold or unknown suppliers hold since 2026-08-04.`.trim();
    }

    out.push({ json: rec });
  }
}
return out;

/** Airtable singleSelect: {id,name} object or bare string — return the name. */
function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Save Profile"
 * Mode: Run Once for Each Item
 */

const item = $input.item.json;

const raw = item.content?.[0]?.text ?? item.text ?? item.message?.content ?? item.response ?? '';

const parsed = parseMappingResponse(raw);

if (!parsed.ok) {
  return {
    json: {
      ...item,
      profileSaved: false,
      needsReview: true,
      exceptionReason: `Column mapping not usable: ${parsed.reason}`,
      reviewHeaderSample: item.headerSample,
      reviewSampleRows: JSON.stringify(item.sampleRows || []).slice(0, 5000),
      modelReply: String(raw).slice(0, 2000),
    },
  };
}

const profileName = [
  item.fileName ? String(item.fileName).replace(/\.[^.]+$/, '') : 'Unknown file',
  item.sectionLabel ? `— ${item.sectionLabel}` : '',
].join(' ').trim();

return {
  json: {
    ...item,
    profileSaved: true,
    needsReview: false,

    'Profile Name': profileName,
    'Header Fingerprint': item.fingerprint,
    'Section Label': item.sectionLabel || '',
    'Header Sample': item.headerSample || '',
    'Column Map': JSON.stringify(parsed.columnMap),
    'Defaults': JSON.stringify(withRequiredDefaults(parsed.defaults)),
    'Confidence': 'High',
    'Created By': 'LLM',
    'Times Used': 0,
    'Status': 'Active',
    'Notes': [
      `Auto-mapped from ${item.fileName || 'an attachment'} on first sight.`,
      parsed.notes ? `Model notes: ${parsed.notes}` : '',
      'REVIEW BEFORE RELYING ON IT: volumeUnit, stockUnit and priceType are',
      'assumptions unless the sheet states them. priceType in particular is a',
      '6-48x error if wrong — drinks lists price per case, FMCG per piece.',
    ].filter(Boolean).join(' '),

    columnMap: parsed.columnMap,
    profileDefaults: withRequiredDefaults(parsed.defaults),
  },
};

function withRequiredDefaults(defaults) {
  const d = { ...(defaults || {}) };
  if (!d.currency) d.currency = 'EUR';
  if (!d.volumeUnit) d.volumeUnit = 'ml';
  if (!d.stockUnit) d.stockUnit = 'cases';
  if (!d.priceType) d.priceType = 'Per Case';
  return d;
}

/**
 * Robust extraction of the column mapping from the model reply.
 *
 * claude-sonnet-4-5 sometimes returns a CHATTY reply: MULTIPLE ```json blocks
 * separated by prose ("Wait, let me correct that:"), the last block being its
 * corrected answer. The old parser stripped a single fence pair then, on
 * failure, grabbed /\{[\s\S]*\}/ — a greedy span from the first { to the last }
 * that glued both objects AND the prose between them into one blob that never
 * JSON.parses. Confirmed cause of parsedCount 0 in execution 9377.
 *
 * We now collect every candidate object — each ```json/``` fenced block, then
 * every brace-balanced { ... } span in the raw text — JSON.parse each, and keep
 * the LAST one that both parses and carries a usable map (productName +
 * buyPrice, not low confidence). On total failure we return { ok:false } so the
 * caller routes the section to review with a clear note rather than emitting 0.
 */
function parseMappingResponse(rawText) {
  const text = String(rawText ?? '');
  const candidates = [];

  const fence = /```(?:json)?\s*([\s\S]*?)```/gi;
  let fm;
  while ((fm = fence.exec(text)) !== null) {
    const body = fm[1] && fm[1].trim();
    if (body) candidates.push(body);
  }

  for (const span of balancedObjects(text)) candidates.push(span);

  let reason = 'model did not return JSON';
  let best = null;
  for (const cand of candidates) {
    let obj;
    try { obj = JSON.parse(cand); } catch { reason = 'model returned malformed JSON'; continue; }
    if (!obj || typeof obj !== 'object') continue;
    const map = obj.columnMap || {};
    if (map.productName === undefined || map.buyPrice === undefined) {
      reason = 'mapping missing productName or buyPrice';
      continue;
    }
    if (String(obj.confidence).toLowerCase() === 'low') {
      reason = `low confidence — ${obj.notes || 'unspecified'}`;
      continue;
    }
    best = obj; // keep scanning — the LAST usable block wins (the correction)
  }

  if (!best) return { ok: false, reason };

  const clean = {};
  for (const [k, v] of Object.entries(best.columnMap || {})) {
    if (Number.isInteger(v) && v >= 0) clean[k] = v;
  }
  return { ok: true, columnMap: clean, defaults: best.defaults || {}, notes: best.notes || '' };
}

/**
 * Every top-level brace-balanced { ... } span in the text, in order. A depth
 * scan (string-aware) so two adjacent objects can never be glued into one
 * unparseable blob the way a single greedy regex does.
 */
function balancedObjects(text) {
  const s = String(text);
  const out = [];
  let depth = 0, start = -1, inStr = false, quote = '', esc = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === quote) inStr = false;
      continue;
    }
    if (c === '"' || c === "'") { inStr = true; quote = c; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      if (depth > 0) { depth--; if (depth === 0 && start >= 0) { out.push(s.slice(start, i + 1)); start = -1; } }
    }
  }
  return out;
}

/**
 * n8n Code node — "Resolve Supplier"
 * Mode: Run Once for All Items
 *
 * Added 2026-08-04. Run-level supplier resolution for the (possibly forwarded)
 * sender. Read Workbook now yields a real fromAddress — the forwarded sender is
 * preferred over the akay.ie forwarder — plus an externalSender flag.
 *
 * Existing suppliers are matched BY EMAIL first, then by a non-generic DOMAIN,
 * so a re-forwarded email from a supplier we already hold (e.g. Halıtlar,
 * sales5@halitlar.com) resolves to the existing record and is never duplicated.
 * Only when no existing supplier matches AND the sender is a plausible external
 * address do we flag needCreate — never for our own akay.ie / offers@akay.ie
 * envelope, which is routed to review (left unresolved) instead.
 */

const GENERIC = new Set([
  'gmail.com', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'yahoo.com',
  'yahoo.co.uk', 'live.com', 'icloud.com', 'aol.com', 'protonmail.com', 'gmx.com',
]);

let meta = {};
try { meta = $('Read Workbook').first().json || {}; } catch (e) { meta = {}; }

const fromAddress = String(meta.fromAddress || '').trim().toLowerCase();
const senderName = String(meta.senderName || '').trim();
const senderDomain = String(meta.senderDomain || (fromAddress.split('@')[1] || '')).toLowerCase();
const externalSender = Boolean(meta.externalSender);

// Suppliers keyed by full email and by unambiguous domain.
const byAddress = new Map();
const byDomain = new Map();
let suppliers = [];
try { suppliers = $('Fetch Suppliers').all().map((i) => i.json || {}); } catch (e) { suppliers = []; }

for (const s of suppliers) {
  const f = s.fields || s;
  if (!s.id) continue;
  const email = String(f['Email'] || '').trim().toLowerCase();
  if (!email) continue;
  const rec = { id: s.id, name: f['Supplier Name'] || null, validityDays: f['Default Validity Days'] ?? null, defaultCurrency: selectName(f['Default Currency']) || null };
  if (!byAddress.has(email)) byAddress.set(email, rec);
  const d = email.split('@')[1];
  if (d) { if (byDomain.has(d)) byDomain.set(d, null); else byDomain.set(d, rec); }
}

let existing = null;
let via = 'unresolved';
if (fromAddress) {
  existing = byAddress.get(fromAddress) || null;
  if (existing) via = `existing supplier by email ${fromAddress}`;
  else if (senderDomain && !GENERIC.has(senderDomain)) {
    const d = byDomain.get(senderDomain);
    if (d) { existing = d; via = `existing supplier by domain ${senderDomain}`; }
  }
}

const needCreate = !existing && externalSender && /@/.test(fromAddress);
const createName = senderName || senderDomain || fromAddress;

return [{
  json: {
    fromAddress,
    senderName,
    senderDomain,
    externalSender,
    envelopeFrom: meta.envelopeFrom || '',
    existingSupplierId: existing ? existing.id : null,
    existingSupplierName: existing ? existing.name : null,
    existingValidityDays: existing ? existing.validityDays : null,
    existingDefaultCurrency: existing ? existing.defaultCurrency : null,
    needCreate,
    createEmail: fromAddress,
    createName,
    via: existing
      ? via
      : needCreate
        ? `auto-create external supplier ${fromAddress}`
        : `no external sender to resolve (envelope ${meta.envelopeFrom || 'unknown'}) — left for review`,
  },
}];

function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Merge Supplier"
 * Mode: Run Once for All Items
 *
 * Added 2026-08-04. Collapses the resolve/create branch back to a single
 * run-level supplier for Build Airtable Payload. Reads the resolution from
 * Resolve Supplier and, when the auto-create branch ran, the freshly created
 * Supplier record from Create Missing Supplier (a created id wins).
 */

let resolved = {};
try { resolved = $('Resolve Supplier').first().json || {}; } catch (e) { resolved = {}; }

let supplierRecordId = resolved.existingSupplierId || null;
let supplierName = resolved.existingSupplierName || null;
let validityDays = resolved.existingValidityDays ?? null;
let defaultCurrency = resolved.existingDefaultCurrency || null;
let via = resolved.via || 'unresolved';

try {
  const created = $('Create Missing Supplier').first().json;
  if (created && created.id) {
    supplierRecordId = created.id;
    const f = created.fields || created;
    supplierName = f['Supplier Name'] || resolved.createName || null;
    validityDays = f['Default Validity Days'] ?? null;
    via = `auto-created supplier ${resolved.createEmail || ''} (Trust Score Medium)`;
  }
} catch (e) { /* auto-create branch did not run — keep the resolved values */ }

return [{
  json: {
    supplierRecordId,
    supplierName,
    validityDays,
    defaultCurrency,
    via,
    fromAddress: resolved.fromAddress || '',
    externalSender: Boolean(resolved.externalSender),
  },
}];

/**
 * n8n Code node — "Select Spreadsheets"
 * Mode: Run Once for All Items
 *
 * Hardened 2026-08-04. Emits ONE item per SPREADSHEET attachment and nothing
 * else. Selection is by file extension (.xlsx/.xlsm/.xltx/.xls/.csv/.tsv,
 * case-insensitive, with trailing spaces/dots tolerated so
 * "3.08.2026 P&G .xlsx" and non-ASCII names like
 * "Ağustos-Nestle_FiyatListesi.xlsx" are kept) OR by spreadsheet MIME type
 * (for a mangled or missing filename). Inline images (image001.jpg signature
 * logos) and every other non-spreadsheet part are dropped. There is NO cap —
 * every matching attachment on the message is processed.
 */

const SPREADSHEET_EXT = /\.(xlsx|xlsm|xltx|xls|csv|tsv)\s*$/i;
const IMAGE_EXT = /\.(jpe?g|png|gif|bmp|svg|webp|tiff?|heic|ico)\s*$/i;
const SPREADSHEET_MIME = /(spreadsheetml|ms-excel|excel|csv|tab-separated|vnd\.oasis\.opendocument\.spreadsheet)/i;
const IMAGE_MIME = /^image\//i;

const out = [];
const skipped = [];

for (const item of $input.all()) {
  const binaries = item.binary || {};

  for (const [binaryKey, binary] of Object.entries(binaries)) {
    const rawName = binary && typeof binary.fileName === 'string' ? binary.fileName : '';
    const name = String(rawName || binaryKey).trim();
    const mime = String((binary && binary.mimeType) || '').trim();

    // Inline images and signature logos: never treat these as spreadsheets.
    const isImage = IMAGE_EXT.test(name) || IMAGE_MIME.test(mime);
    const isSpreadsheet = !isImage && (SPREADSHEET_EXT.test(name) || SPREADSHEET_MIME.test(mime));

    if (isSpreadsheet) {
      out.push({
        json: {
          binaryKey,
          fileName: name,
          mimeType: mime,
          messageId: item.json.id || item.json.messageId || null,
          threadId: item.json.threadId || null,
          subject: item.json.subject || '',
          from: item.json.from || '',
        },
        binary: { [binaryKey]: binary },
      });
    } else {
      skipped.push(name || binaryKey);
    }
  }
}

if (skipped.length) {
  console.log(`Select Spreadsheets: kept ${out.length}, skipped ${skipped.length} non-spreadsheet part(s): ${skipped.join(', ')}`);
}

return out;

/**
 * n8n Code node — "Read Workbook"
 * Mode: Run Once for All Items
 */

const GMAIL_NODE = 'Gmail Trigger';

let meta = {};
try {
  const g = $(GMAIL_NODE).first().json;
  const body = String(g.text || g.textAsHtml || g.html || g.snippet || '');
  const envelope = extractEmail(g.from ?? g.From ?? '');
  const forwarded = forwardedSender(body);
  const effective = (forwarded && forwarded.address) || envelope.address || '';
  const domain = (effective.split('@')[1] || '').toLowerCase();
  meta = {
    sourceMessageId: g.id || g.messageId || null,
    threadId: g.threadId || null,
    fromAddress: effective,
    envelopeFrom: envelope.address || '',
    forwardedFrom: forwarded ? forwarded.address : '',
    senderName: (forwarded && forwarded.name) || envelope.name || '',
    senderDomain: domain,
    senderFromForward: Boolean(forwarded),
    externalSender: Boolean(effective) && /@/.test(effective) && !/@akay\.ie$/i.test(effective),
    subject: g.subject || g.Subject || '',
  };
} catch (e) {
  meta = { sourceMessageId: null, threadId: null, fromAddress: '', envelopeFrom: '', forwardedFrom: '', senderName: '', senderDomain: '', senderFromForward: false, externalSender: false, subject: '' };
}

const items = $input.all();
if (items.length === 0) return [];

const rows = items.map((item) => toCellArray(item.json)).filter((r) => r.length > 0);
if (rows.length < 2) return [];

while (rows.length && rows[rows.length - 1].every((c) => String(c ?? '').trim() === '')) rows.pop();

return [{
  json: {
    ...meta,
    fileName: fileNameFor(items[0]),
    sheetName: sheetNameFor(),
    rows,
    rowCount: rows.length,
  },
}];

function toCellArray(json) {
  if (!json || typeof json !== 'object') return [];

  if (Array.isArray(json.row)) return json.row.map(cell);

  const indexed = Object.keys(json)
    .map((k) => ({ k, i: parseIndex(k) }))
    .filter((x) => x.i !== null)
    .sort((a, b) => a.i - b.i);

  if (indexed.length) {
    const out = [];
    for (const { k, i } of indexed) out[i] = cell(json[k]);
    return Array.from(out, (v) => v ?? '');
  }

  return Object.values(json).map(cell);
}

function parseIndex(key) {
  const m = String(key).match(/^(?:row_|col_|column_)?(\d+)$/i);
  return m ? Number(m[1]) : null;
}

function cell(v) {
  if (v === null || v === undefined) return '';
  if (v instanceof Date) return v;
  return String(v);
}

function fileNameFor(item) {
  const j = item.json || {};
  if (j.fileName) return j.fileName;
  const bin = item.binary && Object.values(item.binary)[0];
  if (bin && bin.fileName) return bin.fileName;
  try {
    const g = $(GMAIL_NODE).first();
    const gb = g.binary && Object.values(g.binary)[0];
    if (gb && gb.fileName) return gb.fileName;
  } catch (e) { /* trigger unavailable — fall through */ }
  return 'unknown.xlsx';
}

function sheetNameFor() {
  try {
    const n = $('Extract From File');
    const name = n.params && (n.params.options?.sheetName || n.params.sheetName);
    if (name) return String(name);
  } catch (e) { /* not resolvable at runtime */ }
  return 'Sheet1';
}

/**
 * Envelope sender as { address, name }. Gmail Trigger (simple:false) delivers
 * `from` as an OBJECT ({ value:[{address,name}], text, html }); the old code
 * String()-ified that to "[object object]", so supplier resolution by sender
 * never matched. Both the object and the raw "Name <addr>" string are handled.
 */
function extractEmail(raw) {
  if (raw && typeof raw === 'object') {
    const v = Array.isArray(raw.value) ? raw.value[0] : null;
    if (v && v.address) return { address: String(v.address).trim().toLowerCase(), name: String(v.name || '').trim() };
    return parseAddr(String(raw.text || raw.html || ''));
  }
  return parseAddr(String(raw));
}

function parseAddr(s) {
  const m = String(s).match(/<([^>]+)>/);
  const address = (m ? m[1] : String(s)).trim().toLowerCase();
  let name = '';
  const nm = String(s).match(/^\s*"?([^"<]+?)"?\s*</);
  if (nm) name = nm[1].trim();
  return { address, name };
}

/**
 * Real supplier from a FORWARDED body header. Offers arrive forwarded into
 * ak@akay.ie / offers@akay.ie, so the envelope sender is the forwarder, not the
 * supplier — the supplier sits in the "From:" line under the forward marker.
 * Returns { address, name } or null; null when the address is our own akay.ie
 * (a forward of our own mail is not a supplier), so we never auto-create from it.
 */
function forwardedSender(text) {
  const src = String(text);
  const fwd = src.match(/-{2,}\s*(?:Forwarded|Original)\s*message\s*-{2,}/i)
           || src.match(/Begin forwarded message:/i);
  if (!fwd || fwd.index === undefined) return null;
  const header = src.slice(fwd.index, fwd.index + 800);
  const m = header.match(/\n\s*\*?\s*From:\s*\*?\s*(.*?)([^\s<>"]+@[^\s<>"]+\.[a-z]{2,})/i);
  if (!m) return null;
  const address = m[2].toLowerCase().replace(/[.,;>]+$/, '');
  if (/@akay\.ie$/i.test(address)) return null;
  const name = String(m[1] || '').replace(/[<"]/g, '').replace(/[-–\s]+$/, '').trim();
  return { address, name };
}

/**
 * n8n Code node — "Detect Header"
 * Mode: Run Once for All Items
 *
 * Splits each worksheet into SECTIONS and emits one item per section.
 */

const HEADER_MIN_SCORE = 3;
const MAX_CONTINUATION_ROWS = 2;

const HEADER_HINTS = [
  'product', 'description', 'brand', 'article', 'item', 'name',
  'price', 'eur', 'usd', 'cost', 'ppc', 'euro',
  'case', 'carton', 'ctn', 'pcs', 'units', 'pack', 'qty', 'quantity', 'stock', 'available',
  'volume', 'size', 'cl', 'ml', 'ltr', 'litre', 'content',
  'abv', 'alc', 'vol',
  'origin', 'country', 'ean', 'barcode', 'sku', 'code',
  'bond', 'customs', 'status', 't1', 't2', 'duty', 'incoterm', 'warehouse', 'delivery',
  'bbd', 'expiry', 'best before', 'moq', 'pallet', 'lead', 'variant', 'comment',
];

const out = [];

for (const input of $input.all()) {
  const item = input.json;
  const rows = item.rows || [];

  const sections = [];
  let i = 0;
  while (i < rows.length) {
    if (scoreAsHeader(rows[i], rows[i + 1]) < HEADER_MIN_SCORE) { i++; continue; }

    let headerCells = (rows[i] || []).map((c) => String(c ?? '').trim());
    let consumed = i;
    for (let n = 1; n <= MAX_CONTINUATION_ROWS; n++) {
      if (!isContinuationRow(rows[i + n], headerCells)) break;
      headerCells = mergeHeaderRow(headerCells, rows[i + n]);
      consumed = i + n;
    }

    sections.push({ start: i, consumed, headerCells });
    i = consumed + 1;
  }

  if (sections.length === 0) {
    out.push({ json: { ...item, rows: undefined, headerFound: false,
      exceptionReason: `No header row detected in "${item.sheetName}"` } });
    continue;
  }

  sections.forEach(({ start, consumed, headerCells }, s) => {
    const end = s + 1 < sections.length ? sections[s + 1].start : rows.length;
    const dataRows = rows.slice(consumed + 1, end)
      .filter((r) => r.some((c) => String(c ?? '').trim() !== ''));

    if (dataRows.length === 0) return;

    if (!hasPriceColumn(headerCells)) {
      out.push({ json: { ...item, rows: undefined, headerFound: false,
        sectionLabel: sectionLabel(headerCells),
        headerSample: headerCells.filter(Boolean).join(' | '),
        exceptionReason: `Section at row ${start} of "${item.sheetName}" has no price column — treated as a non-offer block` } });
      return;
    }

    out.push({
      json: {
        ...item,
        rows: undefined,
        headerFound: true,
        sectionIndex: s,
        sectionCount: sections.length,
        sectionLabel: sectionLabel(headerCells),
        headerRowIndex: start,
        dataStartRow: consumed + 1,
        headerCells,
        dataRows,
        rowCount: dataRows.length,
        fingerprint: fingerprint(headerCells),
        headerSample: headerCells.filter(Boolean).join(' | '),
        sampleRows: dataRows.slice(0, 5),
      },
    });
  });
}

return out;

function scoreAsHeader(row, next) {
  if (!Array.isArray(row)) return 0;

  const cells = row.map((c) => String(c ?? '').trim()).filter(Boolean);
  if (cells.length < 3) return 0;

  const numeric = cells.filter(isNumericish).length;
  if (numeric >= 2) return 0;

  let score = Math.min(cells.length, 8) * 0.5;

  for (const cell of cells) {
    const lower = cell.toLowerCase();
    if (HEADER_HINTS.some((h) => lower.includes(h))) score += 1.5;
  }

  score -= numeric * 1.5;

  if (Array.isArray(next)) {
    const nextCells = next.map((c) => String(c ?? '').trim()).filter(Boolean);
    if (nextCells.length >= 3 && nextCells.some(isNumericish)) score += 2;
  }

  return score;
}

function isContinuationRow(row, header) {
  if (!Array.isArray(row)) return false;

  const cells = row.map((c) => String(c ?? '').trim());
  const filled = cells.filter(Boolean);
  if (filled.length < 2) return false;
  if (filled.length > header.filter(Boolean).length) return false;
  if (filled.some(isNumericish)) return false;

  return filled.filter((c) => c.length <= 15).length >= Math.ceil(filled.length / 2);
}

function mergeHeaderRow(header, contRow) {
  const cont = (contRow || []).map((c) => String(c ?? '').trim());
  const width = Math.max(header.length, cont.length);
  const merged = [];

  for (let i = 0; i < width; i++) {
    const base = header[i] || '';
    const sub = cont[i] || '';
    merged.push(sub && sub.length <= 15 ? `${base} ${sub}`.trim() : base);
  }
  return merged;
}

function sectionLabel(headerCells) {
  const generic = /^(qty|quantity|cartons?|available|description|product|item)\b/i;
  const candidate = headerCells.find((c) => c && c.length <= 30 && !generic.test(c) && !/^\d/.test(c));
  return candidate || headerCells.find(Boolean) || '';
}

function hasPriceColumn(headerCells) {
  const PRICE_TOKENS = ['price', 'euro', 'eur', 'usd', 'gbp', 'cost', 'prijs', 'prezzo', '€', '$', '£'];
  return headerCells.some((c) => {
    const lower = String(c || '').toLowerCase();
    return PRICE_TOKENS.some((t) => lower.includes(t));
  });
}

function isNumericish(v) {
  const s = String(v).replace(/[\s€$£,]/g, '');
  return s !== '' && !Number.isNaN(Number(s.replace(',', '.')));
}

function fingerprint(cells) {
  const norm = cells
    .filter((c) => c && !isNumericish(c))
    .map((c) => c.toLowerCase().replace(/[^a-z0-9]/g, ''))
    .filter(Boolean)
    .sort();
  return 'h' + djb2(norm.join('~')).toString(16).padStart(8, '0');
}

function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  }
  return h;
}

/**
 * n8n Code node — "Match Profile"
 * Mode: Run Once for All Items
 */

const sections = $('Detect Header').all();
const profileItems = $input.all();

const byFingerprint = new Map();
for (const p of profileItems) {
  const rec = p.json || {};
  const fp = rec['Header Fingerprint'];
  if (fp && !byFingerprint.has(fp)) byFingerprint.set(fp, rec);
}

const out = [];
for (const s of sections) {
  const item = s.json || {};

  if (!item.headerFound || !item.fingerprint) {
    out.push({ json: { ...item, profileFound: false } });
    continue;
  }

  const rec = byFingerprint.get(item.fingerprint);
  if (!rec) {
    out.push({ json: { ...item, profileFound: false } });
    continue;
  }

  let columnMap = {};
  let profileDefaults = {};
  try { columnMap = JSON.parse(rec['Column Map'] || '{}'); } catch (e) {}
  try { profileDefaults = JSON.parse(rec['Defaults'] || '{}'); } catch (e) {}

  const supplierLink = rec['Supplier'];
  const supplierRecordId = Array.isArray(supplierLink) && supplierLink.length ? supplierLink[0] : null;

  out.push({
    json: {
      ...item,
      profileFound: true,
      profileId: rec.id || null,
      columnMap,
      profileDefaults,
      supplierRecordId,
      supplierValidityDays: rec['Validity Days'] ?? null,
    },
  });
}

return out;

/**
 * n8n Code node — "Normalize Rows"
 * Mode: Run Once for Each Item
 */

const OPTIONS = {
  currency: ['EUR', 'USD', 'GBP', 'AED', 'SGD', 'Other'],
  unitType: ['Bottle', 'Can', 'Jar', 'Pack', 'Piece', 'Other'],
  priceType: ['Per Case', 'Per Bottle', 'Per Can', 'Per Piece', 'Per Pack', 'Per Jar'],
  bond: ['Bonded', 'T1', 'T2', 'Duty Paid', 'On Floor', 'Other'],
  incoterm: ['EXW', 'FCA', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP', 'Other'],
  warehouse: ['Loendersloot', 'NL', 'Dubai', 'Poland', 'Riga', 'Spain', 'Vietnam',
              'Greece', 'Indonesia', 'Czech', 'Other', 'NewCorp', 'Vergèze', 'Bergamo'],
  category: ['Beer', 'Spirits', 'Champagne', 'Grocery', 'Confectionery',
             'Toiletries', 'Soft Drinks', 'Other FMCG'],
};

const VOLUME_UNIT_FACTOR = { ml: 1, cc: 1, cl: 10, dl: 100, l: 1000, ltr: 1000, litre: 1000 };

const pad = (v) => String(v).padStart(2, '0');

const SYNONYMS = {
  currency: {
    '€': 'EUR', eur: 'EUR', euro: 'EUR', euros: 'EUR',
    $: 'USD', usd: 'USD', dollar: 'USD', usdollar: 'USD',
    '£': 'GBP', gbp: 'GBP', pound: 'GBP', sterling: 'GBP',
    aed: 'AED', dirham: 'AED', sgd: 'SGD',
  },
  bond: {
    bond: 'Bonded', bonded: 'Bonded', underbond: 'Bonded', inbond: 'Bonded',
    t1: 'T1', t2: 'T2', export: 'T1', eu: 'T2', community: 'T2',
    dutypaid: 'Duty Paid', dp: 'Duty Paid', taxpaid: 'Duty Paid',
    onfloor: 'On Floor', floor: 'On Floor', exstock: 'On Floor',
  },
  unitType: {
    bottle: 'Bottle', btl: 'Bottle', flasche: 'Bottle', bouteille: 'Bottle',
    can: 'Can', cans: 'Can', tin: 'Can',
    jar: 'Jar', pack: 'Pack', pouch: 'Pack', piece: 'Piece', pcs: 'Piece', unit: 'Piece',
  },
  category: {
    beer: 'Beer', lager: 'Beer', ale: 'Beer', cider: 'Beer',
    spirit: 'Spirits', spirits: 'Spirits', whisky: 'Spirits', whiskey: 'Spirits',
    vodka: 'Spirits', gin: 'Spirits', rum: 'Spirits', liqueur: 'Spirits',
    cognac: 'Spirits', brandy: 'Spirits', tequila: 'Spirits',
    champagne: 'Champagne', wine: 'Champagne', wines: 'Champagne',
    prosecco: 'Champagne', sparkling: 'Champagne', cava: 'Champagne', bordeaux: 'Champagne',
    softdrink: 'Soft Drinks', softdrinks: 'Soft Drinks', water: 'Soft Drinks',
    juice: 'Soft Drinks', energy: 'Soft Drinks', soda: 'Soft Drinks',
    grocery: 'Grocery', food: 'Grocery',
    confectionery: 'Confectionery', chocolate: 'Confectionery', sweets: 'Confectionery',
    candy: 'Confectionery', biscuit: 'Confectionery',
    toiletries: 'Toiletries', cosmetics: 'Toiletries', personalcare: 'Toiletries',
  },
};

const item = $input.item.json;
const map = item.columnMap || {};
const defaults = item.profileDefaults || {};
const headers = item.headerCells || [];

// No usable column map (the LLM mapping failed / needs review, or a stored
// profile is malformed). Emit ONE visible exception instead of silently
// dropping every row as 0 — so Build Airtable Payload surfaces it and the
// section is routed to review rather than vanishing.
if (map.productName === undefined || map.buyPrice === undefined) {
  return {
    json: {
      fileName: item.fileName,
      sheetName: item.sheetName,
      sourceMessageId: item.sourceMessageId,
      fromAddress: item.fromAddress,
      supplierRecordId: item.supplierRecordId || null,
      profileId: item.profileId || null,
      fingerprint: item.fingerprint,
      parsedCount: 0,
      exceptionCount: 1,
      offers: [],
      exceptions: [{
        sheetRow: item.headerRowIndex ?? null,
        productName: '',
        exceptionReason: item.exceptionReason
          || 'No usable column map (needs review): LLM mapping did not yield productName + buyPrice for this section',
        sourceSheet: `${item.fileName} :: ${item.sheetName}`,
      }],
      needsReview: true,
    },
  };
}

const offers = [];
const exceptions = [];

(item.dataRows || []).forEach((row, i) => {
  const sheetRow = (item.headerRowIndex ?? 0) + 2 + i;
  const get = (field) => {
    const idx = map[field];
    if (idx === undefined || idx === null) return '';
    return String(row[idx] ?? '').trim();
  };

  const productName = get('productName');
  const rawPrice = get('buyPrice');

  if (!productName && !rawPrice) return;

  const problems = [];

  const price = parsePriceCell(rawPrice);
  if (!productName) problems.push('missing product name');
  if (price.value === null) problems.push(`unparseable price "${rawPrice}"`);
  else if (price.ambiguous) problems.push(`ambiguous decimal separator in "${rawPrice}"`);

  const pack = parsePack(get('packFormat') || get('volumeMl') || productName);

  const volume = parseVolume(get('volumeMl'), defaults.volumeUnit)
    ?? pack.volumeMl
    ?? parseVolume(productName, defaults.volumeUnit);
  const pcsCase = parseNumber(get('pcsCase')).value ?? pack.pcsCase;
  const abv = parseAbv(get('abv')) ?? pack.abv ?? parseAbv(productName);
  const weightKg = pack.weightG !== null ? pack.weightG / 1000 : null;

  const bond = coerce('bond', get('bondStatus') || defaults.bondStatus);
  // Currency actually STATED on the row/sheet (symbol on the price, or a
  // dedicated currency column) vs. merely inherited from the profile default.
  // When nothing is stated, the resolved supplier's Default Currency should win
  // downstream (Build Airtable Payload), so track which case this is.
  const statedCurrency = price.currency || coerce('currency', get('currency'));
  const currency = statedCurrency || coerce('currency', defaults.currency);
  const currencyStated = Boolean(statedCurrency);
  if (!currency) problems.push('no currency on row or profile default');

  const brand = get('brand') || guessBrand(productName);

  const record = {
    sheetRow,
    sourceSheet: `${item.fileName} :: ${item.sheetName}`,
    sourceMessageId: item.sourceMessageId,

    brand,
    productName,
    variant: get('variant') || '',
    category: coerce('category', get('category') || defaults.category),
    volumeMl: volume,
    pcsCase: pcsCase ?? defaults.pcsCase ?? null,
    unitType: coerce('unitType', get('unitType') || defaults.unitType) || 'Bottle',
    abv,
    originCountry: get('originCountry') || defaults.originCountry || '',
    bondStatus: bond,
    buyPrice: price.value,
    currency,
    priceType: price.basis
      || coerce('priceType', get('priceType') || defaults.priceType)
      || 'Per Case',
    priceBasisStated: Boolean(price.basis),
    currencyStated,
    weightKg,
    stockCases: toCases(parseNumber(get('stockCases')).value, pcsCase, defaults.stockUnit),
    casesPerPallet: parseNumber(get('casesPerPallet')).value,
    piecesPerPallet: parseNumber(get('piecesPerPallet')).value,
    language: get('language') || '',
    moq: get('moq') || '',
    leadTime: get('leadTime') || '',
    eanUnit: cleanEan(get('eanUnit')),
    eanCase: cleanEan(get('eanCase')),
    bbd: parseDate(get('bbd')),
    incoterm: coerce('incoterm', get('incoterm') || defaults.incoterm),
    warehouse: coerce('warehouse', get('warehouse') || defaults.warehouse),

    productKey: buildProductKey(brand, productName, volume, bond),
  };

  if (problems.length) {
    exceptions.push({ ...record, exceptionReason: problems.join('; ') });
  } else {
    offers.push(record);
  }
});

return {
  json: {
    fileName: item.fileName,
    sheetName: item.sheetName,
    sourceMessageId: item.sourceMessageId,
    fromAddress: item.fromAddress,
    supplierRecordId: item.supplierRecordId || null,
    profileId: item.profileId || null,
    fingerprint: item.fingerprint,
    parsedCount: offers.length,
    exceptionCount: exceptions.length,
    offers,
    exceptions,
  },
};

function parseNumber(raw) {
  if (raw === null || raw === undefined) return { value: null, ambiguous: false };
  let s = String(raw).trim();
  if (!s) return { value: null, ambiguous: false };

  s = s.replace(/euros?|dollars?|pounds?|usd|gbp|aed|sgd|eur|[€$£\s]/gi, '').trim();
  if (!s) return { value: null, ambiguous: false };

  if (/[a-z]/i.test(s)) return { value: null, ambiguous: false };

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');
  let ambiguous = false;

  if (hasDot && hasComma) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
    else s = s.replace(/,/g, '');
  } else if (hasComma) {
    const after = s.split(',')[1] ?? '';
    if (s.split(',').length > 2) s = s.replace(/,/g, '');
    else if (after.length === 3) ambiguous = true;
    else s = s.replace(',', '.');
    if (ambiguous) s = s.replace(',', '.');
  }

  const cleaned = s.replace(/[^0-9.\-]/g, '');
  if (!/\d/.test(cleaned)) return { value: null, ambiguous: false };

  const n = Number(cleaned);
  return Number.isFinite(n) ? { value: n, ambiguous } : { value: null, ambiguous: false };
}

function parsePriceCell(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return { value: null, currency: null, basis: null, ambiguous: false };

  let currency = null;
  if (/€|\beur(o|os)?\b/i.test(s)) currency = 'EUR';
  else if (/£|\bgbp\b|\bpounds?\b/i.test(s)) currency = 'GBP';
  else if (/\$|\busd\b|\bdollars?\b/i.test(s)) currency = 'USD';
  else if (/\baed\b/i.test(s)) currency = 'AED';
  else if (/\bsgd\b/i.test(s)) currency = 'SGD';

  let basis = null;
  const m = s.match(/\/\s*(btl|bottle|cs|case|ctn|carton|pc|pcs|piece|pack|can|jar|unit)\b/i);
  if (m) {
    const k = m[1].toLowerCase();
    if (/^(cs|case|ctn|carton)$/.test(k)) basis = 'Per Case';
    else if (/^(btl|bottle)$/.test(k)) basis = 'Per Bottle';
    else if (/^(pc|pcs|piece|unit)$/.test(k)) basis = 'Per Piece';
    else if (k === 'pack') basis = 'Per Pack';
    else if (k === 'can') basis = 'Per Can';
    else if (k === 'jar') basis = 'Per Jar';
  }

  const numeric = parseNumber(s.replace(/\/\s*[a-z]+\b/gi, ''));

  return { value: numeric.value, currency, basis, ambiguous: numeric.ambiguous };
}

function parsePack(raw) {
  const s = String(raw ?? '').trim();
  const out = { pcsCase: null, volumeMl: null, abv: null, weightG: null };
  if (!s) return out;

  let m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(g|gr|gram|kg)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    const n = Number(m[2].replace(',', '.'));
    out.weightG = /^kg$/i.test(m[3]) ? n * 1000 : n;
    return out;
  }

  m = s.match(/(\d+)\s*[x×\/]\s*(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr)\b/i);
  if (m) {
    out.pcsCase = Number(m[1]);
    out.volumeMl = parseVolume(`${m[2]}${m[3]}`);
    const abv = s.match(/(\d+(?:[.,]\d+)?)\s*%/);
    if (abv) out.abv = Number(abv[1].replace(',', '.'));
    return out;
  }

  m = s.match(/(\d+)\s*\/\s*(\d+(?:[.,]\d+)?)\s*(?:\/\s*(\d+(?:[.,]\d+)?))?/);
  if (m) {
    out.pcsCase = Number(m[1]);
    const mid = Number(m[2].replace(',', '.'));
    out.volumeMl = mid >= 200 ? Math.round(mid) : Math.round(mid * 10);
    if (m[3]) {
      const a = Number(m[3].replace(',', '.'));
      if (a > 0 && a <= 100) out.abv = a;
    }
  }
  return out;
}

function parseVolume(raw, unitHint) {
  const s = String(raw ?? '').toLowerCase();
  if (!s) return null;

  let m = s.match(/(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l|ltr|litre|liter|cc)\b/);
  if (!m) {
    const bare = parseNumber(s).value;
    if (bare === null) return null;

    const factor = VOLUME_UNIT_FACTOR[String(unitHint || '').toLowerCase()];
    if (factor) return Math.round(bare * factor);

    return bare > 0 && bare < 10 ? Math.round(bare * 1000) : Math.round(bare);
  }

  const n = Number(m[1].replace(',', '.'));
  switch (m[2]) {
    case 'ml': case 'cc': return Math.round(n);
    case 'cl': return Math.round(n * 10);
    case 'dl': return Math.round(n * 100);
    default: return Math.round(n * 1000);
  }
}

function toCases(value, pcsCase, stockUnit) {
  if (value === null || value === undefined) return null;
  if (String(stockUnit || '').toLowerCase() !== 'pcs') return value;
  if (!pcsCase || pcsCase <= 0) return null;
  return Math.floor(value / pcsCase);
}

function parseAbv(raw) {
  const s = String(raw ?? '');
  const m = s.match(/(\d+(?:[.,]\d+)?)\s*%/) || s.match(/^(\d+(?:[.,]\d+)?)$/);
  if (!m) return null;
  const n = Number(m[1].replace(',', '.'));
  return n > 0 && n <= 100 ? n : null;
}

function parseDate(raw) {
  if (!raw) return null;
  if (raw instanceof Date && !isNaN(raw)) return raw.toISOString().slice(0, 10);

  const s = String(raw).trim();
  if (!s) return null;

  if (/^\d{5}$/.test(s)) {
    const ms = (Number(s) - 25569) * 86400 * 1000;
    return new Date(ms).toISOString().slice(0, 10);
  }

  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;

  m = s.match(/^([a-z]{3,9})\.?\s+(\d{4})$/i);
  if (m) {
    const months = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    const idx = months.indexOf(m[1].slice(0, 3).toLowerCase());
    if (idx >= 0) return `${m[2]}-${pad(idx + 1)}-01`;
  }

  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
  if (m) {
    let [, a, b, y] = m;
    if (y.length === 2) y = '20' + y;
    const dayFirst = Number(a) > 12 || Number(b) <= 12;
    const day = dayFirst ? a : b;
    const month = dayFirst ? b : a;
    return `${y}-${pad(month)}-${pad(day)}`;
  }

  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
}

function coerce(kind, raw) {
  const s = String(raw ?? '').trim();
  if (!s) return null;

  const exact = OPTIONS[kind].find((o) => o.toLowerCase() === s.toLowerCase());
  if (exact) return exact;

  const key = s.toLowerCase().replace(/[^a-z0-9€$£]/g, '');
  const syn = (SYNONYMS[kind] || {})[key];
  if (syn) return syn;

  for (const [k, v] of Object.entries(SYNONYMS[kind] || {})) {
    if (key.includes(k)) return v;
  }

  return OPTIONS[kind].includes('Other') ? 'Other' : null;
}

function cleanEan(raw) {
  const digits = String(raw ?? '').replace(/\D/g, '');
  return /^\d{8}$|^\d{12,14}$/.test(digits) ? digits : '';
}

function guessBrand(name) {
  const first = String(name).trim().split(/\s+/)[0] || '';
  return first.length > 1 ? first : '';
}

function buildProductKey(brand, name, volumeMl, bond) {
  const n = (v) => String(v ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return [n(brand), n(name), volumeMl ?? '', n(bond)].join('|');
}

/**
 * n8n Code node — "Build Airtable Payload"
 * Mode: Run Once for All Items
 *
 * Turns normalised spreadsheet rows into Airtable Offers records.
 *
 * ── PRODUCT MATCH KEY FIXED 2026-08-03 ──────────────────────────────────────
 * This node used to key the product index on
 *     Brand | Product Name | Volume | Bond status
 * and that is why roughly 89% of offers ended up with no Products link and were
 * therefore invisible to price comparison (Is Cheapest, Cheaper By 5%+).
 *
 * The reason is data, not logic: BRAND IS EMPTY ON THE LARGE MAJORITY OF PRODUCT
 * RECORDS, and Bond/Customs Status is blank on most of them too. Meanwhile the
 * offer side has no brand column on most sheets either, so Normalize Rows falls
 * back to guessBrand() - the FIRST WORD of the product name. So the offer key
 * carried a brand like "ardbeg" while the product key carried an empty string,
 * the two never matched, and every lookup missed. The linking was always being
 * attempted; the key was simply unmatchable.
 *
 * Matching is now on NORMALISED PRODUCT NAME + VOLUME, which are the two fields
 * the Products table actually populates (Product Key there is just the lowercased
 * product name). Brand and Bond are deliberately excluded rather than
 * "improved": including a field that is blank on one side of the comparison can
 * only ever destroy matches.
 *
 * Volume stays IN the key. Dropping it would merge a 70cl and a 1L of the same
 * label into one product and attach offers to the wrong pack size, which is a
 * worse failure than not matching at all.
 *
 * Offer.productKey from Normalize Rows is still carried through for the Notes
 * message and the in-run duplicate guard, but is no longer used for lookup.
 *
 * ── EARLIER CHANGES (2026-07-31, Anil) ─────────────────────────────────────
 *  1. DEFAULT VALIDITY IS NOW 30 DAYS (was 14).
 *  2. RE-INGESTION GUARD. Nothing previously stopped the same email being
 *     parsed twice.
 *  3. SUPPLIER RESOLUTION BY SENDER EMAIL. Previously the supplier came ONLY
 *     from the Sheet Profile's link, so any offer parsed on the LLM
 *     profile-miss path was written with no Supplier at all.
 *  4. EMAIL PROVENANCE ON THE RECORD. Sender, subject and thread are now
 *     written into Notes.
 *
 * Also: offers whose Product does not match are CREATED rather than discarded.
 * They previously went to a toReview array that nothing ever wrote, so with
 * Create Offers enabled they would have been silently dropped. The Products link
 * is left blank and the offer is flagged in Notes; the hourly "Link Offers To
 * Products" workflow then picks it up and can create the Product if needed.
 */

// Raised from 14 to 30 by Anil, 2026-07-31. Used only when the resolved
// supplier has no Default Validity Days of its own.
const FALLBACK_VALIDITY_DAYS = 30;

// Formula and lookup fields — writing to any of these errors the batch.
// Supplier Email/Country/Trust are LOOKUPS through the Supplier link, so
// linking the supplier is what populates them; they must never be written.
const READ_ONLY = new Set([
  'Sell Price', 'Pack Format', 'Is Expired', 'Auto Expiry Date', 'Send Eligible',
  'Public Listing', 'Public Product Description', 'Public Spec', 'Price Display',
  'Public Terms', 'Stock Display', 'whatsapp link',
  'Supplier Name', 'Supplier Email', 'Supplier Country',
  'Supplier Trust Level', 'Supplier Payment Terms',
]);

const products  = nodeRows('Fetch Products');
const suppliers = nodeRows('Fetch Suppliers');
const ingested  = nodeRows('Fetch Ingested Message IDs');
const sections  = $('Normalize Rows').all().map((s) => s.json || {});

const today = new Date().toISOString().slice(0, 10);

const productIndex   = buildProductIndex(products);
const supplierByMail = buildSupplierIndex(suppliers);
const alreadyIngested = new Set(
  ingested.map((r) => normaliseMessageId((r.fields || r)['Source Message ID'])).filter(Boolean)
);

const toCreate   = [];
const skipped    = [];
const exceptions = [];
const summaries  = [];

// Guards against the same row being emitted twice inside ONE run — possible
// when two detected sections overlap on the same block of the sheet.
const seenInRun = new Set();

for (const item of sections) {
  const msgId = normaliseMessageId(item.sourceMessageId);

  // ---- Re-ingestion guard -------------------------------------------------
  // The ID set was read once at the start of this run, so it reflects what was
  // in Airtable BEFORE this execution. A message ID already present therefore
  // means this email was ingested on an earlier run, and the whole section is
  // skipped. It does NOT mean "this row is a duplicate of another row in the
  // same workbook" — one email legitimately produces many offers sharing one
  // message ID, which is exactly why this check happens per SECTION and not
  // per offer.
  if (msgId && alreadyIngested.has(msgId)) {
    skipped.push({
      fileName: item.fileName,
      sheetName: item.sheetName,
      sourceMessageId: item.sourceMessageId,
      offersSkipped: (item.offers || []).length,
      reason: `Message ${msgId} is already present in Offers — email previously ingested, nothing created`,
    });
    summaries.push(`${item.fileName} :: ${item.sheetName} — SKIPPED, already ingested`);
    continue;
  }

  // ---- Supplier resolution ------------------------------------------------
  const resolved = resolveSupplier(item, supplierByMail);

  // Validity comes from the supplier record when we have one. The old code read
  // rec['Validity Days'] off the Sheet Profile, a field that does not exist
  // there — the real one is Suppliers.Default Validity Days — so every offer
  // silently fell back to the default.
  const validityDays = Number(resolved.validityDays) > 0
    ? Number(resolved.validityDays)
    : FALLBACK_VALIDITY_DAYS;

  let created = 0;
  let unlinked = 0;

  for (const offer of item.offers || []) {
    const rowKey = [msgId, offer.productKey, offer.buyPrice].join('~');
    if (seenInRun.has(rowKey)) continue;
    seenInRun.add(rowKey);

    // Name + volume, NOT the brand/bond key — see the header note.
    const matchKey = productMatchKey(offer.productName, offer.volumeMl);
    const productId = productIndex.get(matchKey) || null;

    // Currency fallback: when the sheet stated no currency, apply the resolved
    // supplier's Default Currency (e.g. Halitlar = USD). A stated currency
    // always wins; with no stated currency and no supplier default, the
    // profile default carried on the offer stands.
    const offerCurrency = (!offer.currencyStated && resolved.defaultCurrency)
      ? resolved.defaultCurrency
      : offer.currency;

    const fields = {
      'Offer Name': buildOfferName(offer, resolved.supplierName),
      'Status': 'Live',
      'Offer Date': today,
      'Auto Expiry Days': validityDays,

      'Brand': offer.brand || '',
      'Product Name': offer.productName,
      'Variant': offer.variant || '',
      'Volume ML': offer.volumeMl,
      'PCS/Case': offer.pcsCase,
      'Unit Type': offer.unitType,
      'ABV': offer.abv,
      'Origin Country': offer.originCountry || '',
      'Bond/Customs Status': offer.bondStatus,
      'Buy Price': offer.buyPrice,
      'Currency': offerCurrency,
      'Price Type': offer.priceType,
      'Stock Cases': offer.stockCases,
      'Weight KG': offer.weightKg,
      'Cases per Pallet': offer.casesPerPallet,
      'Pieces per Pallet': offer.piecesPerPallet,
      'Language': offer.language || '',
      'MOQ': offer.moq || '',
      'Lead Time': offer.leadTime || '',
      'EAN Unit': offer.eanUnit || '',
      'EAN Case': offer.eanCase || '',
      'BBD': offer.bbd,
      'Incoterm': offer.incoterm,
      'Warehouse': offer.warehouse,

      'Source Sheet': offer.sourceSheet,
      'Source Message ID': item.sourceMessageId || '',
      'Notes': buildNotes(item, offer, resolved, productId, matchKey, today),
    };

    if (offer.category) fields['Category'] = offer.category;

    // Linking the Supplier is also what populates the read-only Supplier Email,
    // Supplier Country and Supplier Trust Level lookups on the offer.
    if (resolved.supplierRecordId) fields['Supplier'] = [resolved.supplierRecordId];

    if (productId) fields['Products'] = [productId];
    else unlinked++;

    toCreate.push({ fields: stripEmpty(fields) });
    created++;
  }

  for (const e of item.exceptions || []) {
    exceptions.push({
      sheetRow: e.sheetRow,
      productName: e.productName,
      reason: e.exceptionReason,
      sourceSheet: e.sourceSheet,
    });
  }

  summaries.push(
    `${item.fileName} :: ${item.sheetName} — ${created} offers ` +
    `(${unlinked} without a Product link), ` +
    `${(item.exceptions || []).length} bad rows, ` +
    `supplier: ${resolved.supplierName || 'UNRESOLVED'} via ${resolved.via}, ` +
    `expiry ${validityDays}d`
  );
}

return [{
  json: {
    createCount: toCreate.length,
    skippedCount: skipped.length,
    exceptionCount: exceptions.length,
    toCreate,
    skipped,
    exceptions,
    summary: summaries.join(' | ') || 'nothing to do',
  },
}];

// ── helpers ──────────────────────────────────────────────────────────

/** Rows from a named Airtable node, or [] when it did not run. */
function nodeRows(name) {
  try { return $(name).all().map((i) => i.json || {}); }
  catch (e) { return []; }
}

/**
 * Strip the mailbox prefix from a Gmail message ID before comparing.
 *
 * The base holds BOTH "19fadb488e2d3ea9" and
 * "gmail:offers@akay.ie:19fadb488e2d3ea9" for the same message. They do not
 * string-match, so an exact comparison silently misses one of the two formats —
 * this is the confirmed cause of the CSE Ltd. Jameson, Newport Global, EZATA
 * Drinks and Yael Dahan duplicate batches. Take the last colon-separated
 * segment and lowercase it.
 */
function normaliseMessageId(v) {
  const s = String(v ?? '').trim();
  if (!s) return '';
  const parts = s.split(':');
  return parts[parts.length - 1].trim().toLowerCase();
}

/**
 * The single definition of how an Offer is matched to a Product.
 *
 * Punctuation and spacing are stripped entirely, so "Aberlour A'Bunadh Batch 77"
 * and "Aberlour ABunadh Batch 77" agree - supplier sheets are inconsistent about
 * apostrophes, hyphens and double spaces, and those differences are never
 * meaningful. Volume is kept as a plain number so 700 and "700" agree.
 */
function productMatchKey(name, volumeMl) {
  const n = String(name ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const v = (volumeMl === null || volumeMl === undefined || volumeMl === '') ? '' : Number(volumeMl);
  return n + '|' + v;
}

function buildProductIndex(rows) {
  const index = new Map();
  for (const p of rows) {
    const f = p.fields || p;
    if (!p.id) continue;
    const key = productMatchKey(f['Product Name'], f['Volume ML']);
    if (!index.has(key)) index.set(key, p.id);
  }
  return index;
}

/** Suppliers keyed by full email address AND by bare domain. */
function buildSupplierIndex(rows) {
  const byAddress = new Map();
  const byDomain = new Map();

  for (const s of rows) {
    const f = s.fields || s;
    if (!s.id) continue;
    const email = String(f['Email'] || '').trim().toLowerCase();
    if (!email) continue;

    const rec = {
      id: s.id,
      name: f['Supplier Name'] || null,
      validityDays: f['Default Validity Days'] ?? null,
      defaultCurrency: selectName(f['Default Currency']) || null,
      status: f['Status'] || null,
      skip: Boolean(f['Skip Offer Ingestion']),
    };

    if (!byAddress.has(email)) byAddress.set(email, rec);

    const domain = email.split('@')[1];
    // A domain is only a usable key while exactly one supplier uses it. Two
    // suppliers on one domain (or a shared host like gmail.com) makes the
    // domain ambiguous, so it is removed rather than guessed at.
    if (domain) {
      if (byDomain.has(domain)) byDomain.set(domain, null);
      else byDomain.set(domain, rec);
    }
  }
  return { byAddress, byDomain };
}

/**
 * Work out which supplier this workbook belongs to.
 *
 * Order matters. The Sheet Profile's own Supplier link is authoritative because
 * a human (or a reviewed LLM mapping) tied that header fingerprint to that
 * supplier. Only when there is no profile link do we fall back to the sending
 * address — which is the case that used to produce offers with no supplier at
 * all, on the profile-miss path.
 *
 * Generic mailbox domains are deliberately NOT domain-matched: several
 * suppliers use hotmail/gmail addresses, so a domain hit there means nothing.
 */
function resolveSupplier(item, index) {
  const GENERIC = new Set([
    'gmail.com', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'yahoo.com',
    'yahoo.co.uk', 'live.com', 'icloud.com', 'aol.com', 'protonmail.com', 'gmx.com',
  ]);

  if (item.supplierRecordId) {
    // Enrich from the fetched supplier list when we can, for validity days and
    // the name used in the internal Offer Name.
    const match = [...index.byAddress.values()].find((s) => s.id === item.supplierRecordId);
    return {
      supplierRecordId: item.supplierRecordId,
      supplierName: match ? match.name : null,
      validityDays: match ? match.validityDays : null,
      defaultCurrency: match ? match.defaultCurrency : null,
      via: 'sheet profile link',
    };
  }

  const from = String(item.fromAddress || '').trim().toLowerCase();
  if (from) {
    const exact = index.byAddress.get(from);
    if (exact) {
      return {
        supplierRecordId: exact.id,
        supplierName: exact.name,
        validityDays: exact.validityDays,
        defaultCurrency: exact.defaultCurrency,
        via: `sender address ${from}`,
      };
    }

    const domain = from.split('@')[1];
    if (domain && !GENERIC.has(domain)) {
      const byDom = index.byDomain.get(domain);
      if (byDom) {
        return {
          supplierRecordId: byDom.id,
          supplierName: byDom.name,
          validityDays: byDom.validityDays,
          defaultCurrency: byDom.defaultCurrency,
          via: `sender domain ${domain}`,
        };
      }
    }
  }

  // Resolve-or-auto-create fallback. A supplier matched from — or auto-created
  // for — the forwarded sender at run level by the Resolve Supplier / Create
  // Missing Supplier / Merge Supplier branch. Reached only when neither the
  // Sheet Profile link nor a direct sender match found one. When this is also
  // empty the sender was our own akay.ie (or otherwise not external): the offer
  // is left UNRESOLVED with a NEEDS ATTENTION note rather than inventing a
  // supplier from our own address.
  const run = runSupplier();
  if (run && run.supplierRecordId) {
    return {
      supplierRecordId: run.supplierRecordId,
      supplierName: run.supplierName || null,
      validityDays: run.validityDays ?? null,
      defaultCurrency: run.defaultCurrency || null,
      via: run.via || 'resolve-or-auto-create',
    };
  }

  return { supplierRecordId: null, supplierName: null, validityDays: null, defaultCurrency: null, via: 'UNRESOLVED' };
}

/**
 * Internal provenance for the offer. Notes is flagged INTERNAL ONLY on this
 * table and must never be mapped into Softr, which is why the sender address
 * and thread ID can live here. Public text belongs in Public Note.
 */
function buildNotes(item, offer, resolved, productId, matchKey, today) {
  const lines = [
    `Ingested from spreadsheet ${offer.sourceSheet} row ${offer.sheetRow} on ${today}.`,
    `Email: from ${item.fromAddress || '(sender unknown)'}` +
      `${item.subject ? `, subject "${item.subject}"` : ''}` +
      `${item.threadId ? `, thread ${item.threadId}` : ''}.`,
    `Supplier resolved via ${resolved.via}` +
      `${resolved.supplierName ? ` (${resolved.supplierName})` : ''}.`,
  ];

  if (!resolved.supplierRecordId) {
    lines.push('NEEDS ATTENTION: no Supplier could be matched from the Sheet Profile or the sending address. Set the Supplier link by hand — without it this offer has no supplier email, country or trust level.');
  }
  if (!productId) {
    lines.push(`No Product matched name+volume key "${matchKey}", so the Products link is blank and this offer is not yet visible to price comparison. The hourly Link Offers To Products workflow will match it, or create the Product if the offer has both a name and a volume.`);
  }
  return lines.join(' ');
}

/**
 * Offer Name is the primary field and is explicitly INTERNAL, so it may carry
 * the supplier name. Public display uses Public Product Description.
 */
function buildOfferName(offer, supplierName) {
  const parts = [offer.brand, offer.productName, offer.variant].filter(Boolean);
  const spec = offer.volumeMl ? `${offer.volumeMl}ml` : '';
  const supplier = supplierName ? ` - ${supplierName}` : '';
  return `${parts.join(' ')}${spec ? ' ' + spec : ''}${supplier} ${new Date().toISOString().slice(0, 10)}`.trim();
}

/** Airtable rejects null on some field types; omit rather than send empties. */
function stripEmpty(fields) {
  const out = {};
  for (const [k, v] of Object.entries(fields)) {
    if (READ_ONLY.has(k)) continue;
    if (v === null || v === undefined || v === '') continue;
    out[k] = v;
  }
  return out;
}

/**
 * Run-level supplier from the Resolve/Create/Merge branch (Merge Supplier).
 * Empty when that branch produced no supplier — e.g. an internal-only sender.
 */
function runSupplier() {
  try { return $('Merge Supplier').first().json || null; }
  catch (e) { return null; }
}

/** Airtable singleSelect value: {id,name} object over the REST client, or a
 * bare string. Return the plain name either way. */
function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Expand Offers"
 * Mode: Run Once for All Items
 *
 * Expands the matched toCreate[] into one flat record item each for
 * Create Offers (autoMapInputData), and stamps the trust-driven Offer
 * Approval Status on every record (Anil, 2026-08-04):
 *
 *   supplier Trust Score High, Medium or Low  -> Approved
 *   Trust = Hold, or no resolvable supplier   -> Awaiting Approval
 *
 * Offer Approval Status is a PROCESSING status feeding Send Eligible and the
 * Public Listing formula. It is NOT a human control point — the two human
 * approvals (Listing Approved on the website, Gate 2 dispatch approval, each
 * by Anil or Annika) are never written by ingestion, so an auto-approved
 * offer still cannot reach the public site or a client inbox on its own.
 *
 * Trust is read per record via the Supplier link id against the run's
 * Fetch Suppliers snapshot. A Supplier id NOT in that snapshot was created
 * THIS run by Create Missing Supplier, which always writes Trust = Medium
 * (Hard Rule 8) -> Approved.
 */

const AUTO_APPROVE = new Set(['high', 'medium', 'low']);

// Supplier id -> Trust Score name, from the run's supplier snapshot.
const trustById = new Map();
try {
  for (const s of $('Fetch Suppliers').all()) {
    const j = s.json || {};
    const f = j.fields || j;
    if (j.id) trustById.set(j.id, selectName(f['Trust Score']));
  }
} catch (e) { /* snapshot unavailable — falls through to Awaiting Approval */ }

const out = [];
for (const it of $input.all()) {
  const recs = (it.json && it.json.toCreate) || [];
  for (const r of recs) {
    const rec = r.fields || r;

    const supplierId = Array.isArray(rec['Supplier']) && rec['Supplier'].length
      ? rec['Supplier'][0] : null;

    let trust = supplierId ? trustById.get(supplierId) : null;
    // Not in the snapshot but linked => auto-created this run at Medium.
    if (supplierId && trust === undefined) trust = 'Medium';

    const approved = AUTO_APPROVE.has(String(trust || '').toLowerCase());
    rec['Offer Approval Status'] = approved ? 'Approved' : 'Awaiting Approval';
    if (!approved) {
      rec['Notes'] = `${rec['Notes'] || ''} HELD at Awaiting Approval: supplier trust is ${trust || 'unknown/unresolved'} — only Hold or unknown suppliers hold since 2026-08-04.`.trim();
    }

    out.push({ json: rec });
  }
}
return out;

/** Airtable singleSelect: {id,name} object or bare string — return the name. */
function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Save Profile"
 * Mode: Run Once for Each Item
 */

const item = $input.item.json;

const raw = item.content?.[0]?.text ?? item.text ?? item.message?.content ?? item.response ?? '';

const parsed = parseMappingResponse(raw);

if (!parsed.ok) {
  return {
    json: {
      ...item,
      profileSaved: false,
      needsReview: true,
      exceptionReason: `Column mapping not usable: ${parsed.reason}`,
      reviewHeaderSample: item.headerSample,
      reviewSampleRows: JSON.stringify(item.sampleRows || []).slice(0, 5000),
      modelReply: String(raw).slice(0, 2000),
    },
  };
}

const profileName = [
  item.fileName ? String(item.fileName).replace(/\.[^.]+$/, '') : 'Unknown file',
  item.sectionLabel ? `— ${item.sectionLabel}` : '',
].join(' ').trim();

return {
  json: {
    ...item,
    profileSaved: true,
    needsReview: false,

    'Profile Name': profileName,
    'Header Fingerprint': item.fingerprint,
    'Section Label': item.sectionLabel || '',
    'Header Sample': item.headerSample || '',
    'Column Map': JSON.stringify(parsed.columnMap),
    'Defaults': JSON.stringify(withRequiredDefaults(parsed.defaults)),
    'Confidence': 'High',
    'Created By': 'LLM',
    'Times Used': 0,
    'Status': 'Active',
    'Notes': [
      `Auto-mapped from ${item.fileName || 'an attachment'} on first sight.`,
      parsed.notes ? `Model notes: ${parsed.notes}` : '',
      'REVIEW BEFORE RELYING ON IT: volumeUnit, stockUnit and priceType are',
      'assumptions unless the sheet states them. priceType in particular is a',
      '6-48x error if wrong — drinks lists price per case, FMCG per piece.',
    ].filter(Boolean).join(' '),

    columnMap: parsed.columnMap,
    profileDefaults: withRequiredDefaults(parsed.defaults),
  },
};

function withRequiredDefaults(defaults) {
  const d = { ...(defaults || {}) };
  if (!d.currency) d.currency = 'EUR';
  if (!d.volumeUnit) d.volumeUnit = 'ml';
  if (!d.stockUnit) d.stockUnit = 'cases';
  if (!d.priceType) d.priceType = 'Per Case';
  return d;
}

/**
 * Robust extraction of the column mapping from the model reply.
 *
 * claude-sonnet-4-5 sometimes returns a CHATTY reply: MULTIPLE ```json blocks
 * separated by prose ("Wait, let me correct that:"), the last block being its
 * corrected answer. The old parser stripped a single fence pair then, on
 * failure, grabbed /\{[\s\S]*\}/ — a greedy span from the first { to the last }
 * that glued both objects AND the prose between them into one blob that never
 * JSON.parses. Confirmed cause of parsedCount 0 in execution 9377.
 *
 * We now collect every candidate object — each ```json/``` fenced block, then
 * every brace-balanced { ... } span in the raw text — JSON.parse each, and keep
 * the LAST one that both parses and carries a usable map (productName +
 * buyPrice, not low confidence). On total failure we return { ok:false } so the
 * caller routes the section to review with a clear note rather than emitting 0.
 */
function parseMappingResponse(rawText) {
  const text = String(rawText ?? '');
  const candidates = [];

  const fence = /```(?:json)?\s*([\s\S]*?)```/gi;
  let fm;
  while ((fm = fence.exec(text)) !== null) {
    const body = fm[1] && fm[1].trim();
    if (body) candidates.push(body);
  }

  for (const span of balancedObjects(text)) candidates.push(span);

  let reason = 'model did not return JSON';
  let best = null;
  for (const cand of candidates) {
    let obj;
    try { obj = JSON.parse(cand); } catch { reason = 'model returned malformed JSON'; continue; }
    if (!obj || typeof obj !== 'object') continue;
    const map = obj.columnMap || {};
    if (map.productName === undefined || map.buyPrice === undefined) {
      reason = 'mapping missing productName or buyPrice';
      continue;
    }
    if (String(obj.confidence).toLowerCase() === 'low') {
      reason = `low confidence — ${obj.notes || 'unspecified'}`;
      continue;
    }
    best = obj; // keep scanning — the LAST usable block wins (the correction)
  }

  if (!best) return { ok: false, reason };

  const clean = {};
  for (const [k, v] of Object.entries(best.columnMap || {})) {
    if (Number.isInteger(v) && v >= 0) clean[k] = v;
  }
  return { ok: true, columnMap: clean, defaults: best.defaults || {}, notes: best.notes || '' };
}

/**
 * Every top-level brace-balanced { ... } span in the text, in order. A depth
 * scan (string-aware) so two adjacent objects can never be glued into one
 * unparseable blob the way a single greedy regex does.
 */
function balancedObjects(text) {
  const s = String(text);
  const out = [];
  let depth = 0, start = -1, inStr = false, quote = '', esc = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === quote) inStr = false;
      continue;
    }
    if (c === '"' || c === "'") { inStr = true; quote = c; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      if (depth > 0) { depth--; if (depth === 0 && start >= 0) { out.push(s.slice(start, i + 1)); start = -1; } }
    }
  }
  return out;
}

/**
 * n8n Code node — "Resolve Supplier"
 * Mode: Run Once for All Items
 *
 * Added 2026-08-04. Run-level supplier resolution for the (possibly forwarded)
 * sender. Read Workbook now yields a real fromAddress — the forwarded sender is
 * preferred over the akay.ie forwarder — plus an externalSender flag.
 *
 * Existing suppliers are matched BY EMAIL first, then by a non-generic DOMAIN,
 * so a re-forwarded email from a supplier we already hold (e.g. Halıtlar,
 * sales5@halitlar.com) resolves to the existing record and is never duplicated.
 * Only when no existing supplier matches AND the sender is a plausible external
 * address do we flag needCreate — never for our own akay.ie / offers@akay.ie
 * envelope, which is routed to review (left unresolved) instead.
 */

const GENERIC = new Set([
  'gmail.com', 'hotmail.com', 'hotmail.fr', 'outlook.com', 'yahoo.com',
  'yahoo.co.uk', 'live.com', 'icloud.com', 'aol.com', 'protonmail.com', 'gmx.com',
]);

let meta = {};
try { meta = $('Read Workbook').first().json || {}; } catch (e) { meta = {}; }

const fromAddress = String(meta.fromAddress || '').trim().toLowerCase();
const senderName = String(meta.senderName || '').trim();
const senderDomain = String(meta.senderDomain || (fromAddress.split('@')[1] || '')).toLowerCase();
const externalSender = Boolean(meta.externalSender);

// Suppliers keyed by full email and by unambiguous domain.
const byAddress = new Map();
const byDomain = new Map();
let suppliers = [];
try { suppliers = $('Fetch Suppliers').all().map((i) => i.json || {}); } catch (e) { suppliers = []; }

for (const s of suppliers) {
  const f = s.fields || s;
  if (!s.id) continue;
  const email = String(f['Email'] || '').trim().toLowerCase();
  if (!email) continue;
  const rec = { id: s.id, name: f['Supplier Name'] || null, validityDays: f['Default Validity Days'] ?? null, defaultCurrency: selectName(f['Default Currency']) || null };
  if (!byAddress.has(email)) byAddress.set(email, rec);
  const d = email.split('@')[1];
  if (d) { if (byDomain.has(d)) byDomain.set(d, null); else byDomain.set(d, rec); }
}

let existing = null;
let via = 'unresolved';
if (fromAddress) {
  existing = byAddress.get(fromAddress) || null;
  if (existing) via = `existing supplier by email ${fromAddress}`;
  else if (senderDomain && !GENERIC.has(senderDomain)) {
    const d = byDomain.get(senderDomain);
    if (d) { existing = d; via = `existing supplier by domain ${senderDomain}`; }
  }
}

const needCreate = !existing && externalSender && /@/.test(fromAddress);
const createName = senderName || senderDomain || fromAddress;

return [{
  json: {
    fromAddress,
    senderName,
    senderDomain,
    externalSender,
    envelopeFrom: meta.envelopeFrom || '',
    existingSupplierId: existing ? existing.id : null,
    existingSupplierName: existing ? existing.name : null,
    existingValidityDays: existing ? existing.validityDays : null,
    existingDefaultCurrency: existing ? existing.defaultCurrency : null,
    needCreate,
    createEmail: fromAddress,
    createName,
    via: existing
      ? via
      : needCreate
        ? `auto-create external supplier ${fromAddress}`
        : `no external sender to resolve (envelope ${meta.envelopeFrom || 'unknown'}) — left for review`,
  },
}];

function selectName(v) {
  const a = Array.isArray(v) ? v[0] : v;
  if (a === null || a === undefined) return null;
  return typeof a === 'object' ? (a.name || null) : String(a);
}

/**
 * n8n Code node — "Merge Supplier"
 * Mode: Run Once for All Items
 *
 * Added 2026-08-04. Collapses the resolve/create branch back to a single
 * run-level supplier for Build Airtable Payload. Reads the resolution from
 * Resolve Supplier and, when the auto-create branch ran, the freshly created
 * Supplier record from Create Missing Supplier (a created id wins).
 */

let resolved = {};
try { resolved = $('Resolve Supplier').first().json || {}; } catch (e) { resolved = {}; }

let supplierRecordId = resolved.existingSupplierId || null;
let supplierName = resolved.existingSupplierName || null;
let validityDays = resolved.existingValidityDays ?? null;
let defaultCurrency = resolved.existingDefaultCurrency || null;
let via = resolved.via || 'unresolved';

try {
  const created = $('Create Missing Supplier').first().json;
  if (created && created.id) {
    supplierRecordId = created.id;
    const f = created.fields || created;
    supplierName = f['Supplier Name'] || resolved.createName || null;
    validityDays = f['Default Validity Days'] ?? null;
    via = `auto-created supplier ${resolved.createEmail || ''} (Trust Score Medium)`;
  }
} catch (e) { /* auto-create branch did not run — keep the resolved values */ }

return [{
  json: {
    supplierRecordId,
    supplierName,
    validityDays,
    defaultCurrency,
    via,
    fromAddress: resolved.fromAddress || '',
    externalSender: Boolean(resolved.externalSender),
  },
}];
